// GERADO por scripts/gen-site-template.mjs a partir de site/loja.html — NÃO edite à mão.
export const SITE_LOJA_HTML = "<!doctype html>\n<html lang=\"pt-BR\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1, viewport-fit=cover\">\n<title>Big Tricot · Catálogo</title>\n<link rel=\"preconnect\" href=\"https://fonts.googleapis.com\">\n<link rel=\"preconnect\" href=\"https://fonts.gstatic.com\" crossorigin>\n<link href=\"https://fonts.googleapis.com/css2?family=Cormorant+Garamond:wght@500;600;700&family=Montserrat:wght@400;500;600;700&display=swap\" rel=\"stylesheet\">\n<style>\n  :root{\n    --bg:#f7f4ee; --card:#ffffff; --ink:#24201d; --muted:#8a8073; --line:#e8e2d7;\n    --accent:#ad5033; --accent-soft:#bd6245; --ok:#5d7a4a; --chip:#efe7d8;\n    --shadow:0 1px 2px rgba(60,48,32,.05),0 10px 26px rgba(60,48,32,.06);\n    --radius:14px;\n  }\n  *{box-sizing:border-box}\n  html,body{margin:0}\n  body{background:var(--bg); color:var(--ink); font-family:'Montserrat',system-ui,-apple-system,sans-serif; -webkit-font-smoothing:antialiased; line-height:1.45}\n  .serif{font-family:\"Cormorant Garamond\",Georgia,serif}\n  /* banner full-width, começa no TOPO da página (sem faixa preta em cima) */\n  /* Proporção original 1920×600 (3.2:1): a altura acompanha a largura, sem cortar o topo. */\n  .banner{position:relative; width:100%; aspect-ratio:1920/600; max-height:600px; overflow:hidden; background:#181615}\n  .b-slide{position:absolute; inset:0; opacity:0; transition:opacity .8s ease; display:flex; align-items:center; pointer-events:none}\n  .b-slide.on{opacity:1; pointer-events:auto}\n  .b-link{position:absolute; inset:0; display:flex; align-items:center; text-decoration:none; color:inherit}\n  .b-dots{position:absolute; left:0; right:0; bottom:14px; z-index:5; display:flex; gap:8px; justify-content:center}\n  .b-dot{width:9px; height:9px; padding:0; border:0; border-radius:50%; background:rgba(255,255,255,.45); cursor:pointer; transition:width .2s, background .2s}\n  .b-dot.on{background:#fff; width:22px; border-radius:5px}\n  .b-arrow{position:absolute; top:50%; transform:translateY(-50%); z-index:5; width:40px; height:40px; border-radius:50%; border:0; background:rgba(255,255,255,.18); color:#fff; font-size:24px; line-height:1; cursor:pointer; display:flex; align-items:center; justify-content:center}\n  .b-arrow:hover{background:rgba(255,255,255,.32)}\n  .b-prev{left:14px} .b-next{right:14px}\n  @media(max-width:640px){ .b-arrow{display:none} }\n  @media(prefers-reduced-motion: reduce){ .b-slide{transition:none} }\n  .banner .b-bg{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; object-position:center; z-index:0}\n  .banner .b-shade{position:absolute; inset:0; z-index:1; background:linear-gradient(90deg,rgba(24,22,21,.80) 0%,rgba(24,22,21,.38) 46%,rgba(24,22,21,.08) 100%)}\n  .banner .b-in{position:relative; z-index:2; max-width:1760px; margin:0 auto; width:100%; padding:0 72px; color:#fff}\n  .banner .b-kick{font-size:12px; letter-spacing:.3em; text-transform:uppercase; color:#e7decf; font-weight:500}\n  .banner .b-tit{font-size:48px; font-weight:600; line-height:1.04; letter-spacing:.015em; margin:12px 0 0; max-width:640px}\n  .banner .b-sub{font-size:12px; letter-spacing:.24em; text-transform:uppercase; color:#d8cfc0; margin-top:14px}\n  .banner .b-btn{display:inline-flex; align-items:center; gap:8px; margin-top:22px; background:var(--accent); color:#fff; border:0; border-radius:4px; padding:13px 26px; font-size:12px; letter-spacing:.16em; text-transform:uppercase; font-weight:600; cursor:pointer; text-decoration:none}\n  /* FAIXA PRETA GRAFITE abaixo do banner: busca centralizada + cliente/carrinho à direita */\n  .buscafaixa{background:#181615; padding:0 24px; position:sticky; top:0; z-index:40; min-height:64px; display:flex; align-items:center}\n  /* 3 colunas: [espaço] [busca centralizada] [grupo direito]. Colunas laterais iguais (1fr)\n     garantem que a busca fique no CENTRO real da página, independente dos botões. */\n  .bf-in{width:100%; max-width:1760px; margin:0 auto; display:grid; grid-template-columns:1fr auto 1fr; align-items:center; gap:12px; padding:10px 0}\n  .busca{grid-column:2; justify-self:center; width:400px; max-width:100%; height:44px; box-sizing:border-box; display:flex; align-items:center; gap:9px; background:#fff; border:1px solid #e8e2d7; border-radius:12px; padding:0 14px; box-shadow:0 1px 2px rgba(0,0,0,.14)}\n  .busca .bf-ico{width:18px; height:18px; flex:0 0 auto; stroke:#8a8073; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round}\n  .busca input{border:0; outline:0; background:transparent; width:100%; font-size:14px; color:var(--ink)}\n  .bf-right{grid-column:3; justify-self:end; display:flex; flex-direction:column; align-items:flex-end; gap:5px; min-width:0}\n  .bf-right-top{display:flex; align-items:center; gap:12px}\n  /* Botão Voltar no cabeçalho (só no modo representante) — volta pra área do rep */\n  .bf-left{grid-column:1; justify-self:start; display:flex; align-items:center; gap:12px; min-width:0}\n  .bf-logo{height:36px; width:auto; display:block; flex:0 0 auto}\n  .bf-voltar{display:none; align-items:center; gap:7px; height:40px; padding:0 15px; border:1px solid rgba(255,255,255,.3); background:rgba(255,255,255,.08); color:#f0ebe2; border-radius:10px; font-size:14px; font-weight:600; cursor:pointer}\n  .bf-voltar svg{width:17px; height:17px; stroke:currentColor; fill:none; stroke-width:2.2; stroke-linecap:round; stroke-linejoin:round}\n  body.rep-mode .bf-voltar{display:inline-flex}\n  /* Modo \"só visualização\": esconde carrinho/meus pedidos (rep só vê, não monta pedido) */\n  body.rep-sover .bf-right-top{display:none}\n  /* ...e some com os controles de pedido na ficha do produto (stepper, resumo, botão). */\n  body.rep-sover #sheet .stepper, body.rep-sover #sheet .addcart, body.rep-sover #sheet .resumo{display:none !important}\n  .saud{display:flex; align-items:center; gap:5px; font-size:12px; color:#cfc7ba; white-space:nowrap; min-width:0; max-width:320px}\n  .saud b{color:#f0ebe2; font-weight:600; overflow:hidden; text-overflow:ellipsis; white-space:nowrap}\n  .saud a{flex:0 0 auto}\n  .btn-cart{height:42px; box-sizing:border-box; display:inline-flex; align-items:center; gap:7px; border:1px solid var(--accent); background:var(--accent); color:#fff; border-radius:12px; padding:0 16px; font-weight:600; font-size:13px; cursor:pointer; white-space:nowrap; flex:0 0 auto}\n  .btn-cart .n{background:#fff; color:var(--accent); border-radius:999px; min-width:20px; height:20px; display:inline-flex; align-items:center; justify-content:center; font-size:12px; padding:0 5px}\n  .btn-ghost{height:42px; box-sizing:border-box; display:inline-flex; align-items:center; gap:7px; border:1px solid rgba(255,255,255,.35); background:transparent; color:#e9e2d6; border-radius:12px; padding:0 15px; font-weight:500; font-size:13px; cursor:pointer; white-space:nowrap; flex:0 0 auto; transition:background .15s ease,border-color .15s ease}\n  .btn-ghost:hover{background:rgba(255,255,255,.08); border-color:rgba(255,255,255,.6)}\n  .btn-cart svg,.btn-ghost svg{width:18px; height:18px; flex:0 0 auto; stroke:currentColor; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round}\n  /* Meus pedidos (área do cliente) */\n  /* Área do Representante (R1) — tela cheia com a carteira; otimizada pra tablet (toque). */\n  #repArea{position:fixed; inset:0; z-index:900; background:#f4f0ea; overflow:auto; display:none}\n  /* Cobertura instantânea no portal do rep (?rep=1): evita o \"flash\" do catálogo\n     enquanto a área do representante carrega. Some assim que a área/login aparece. */\n  .rep-boot{display:none}\n  html.portal-rep .rep-boot{display:flex; position:fixed; inset:0; z-index:800; background:#f4f0ea; align-items:center; justify-content:center}\n  .rep-boot-in{display:flex; flex-direction:column; align-items:center; gap:14px; color:#8a8073; font-size:14.5px; font-family:system-ui,-apple-system,sans-serif}\n  .rep-boot-sp{width:34px; height:34px; border:3px solid #DCE3EC; border-top-color:#2c3e50; border-radius:50%; animation:repspin .8s linear infinite}\n  @keyframes repspin{to{transform:rotate(360deg)}}\n  .rep-top{position:sticky; top:0; z-index:2; background:#2c3e50; color:#fff; display:flex; align-items:center; justify-content:space-between; gap:12px; padding:14px 20px}\n  .rep-hello{font-size:12px; letter-spacing:.12em; text-transform:uppercase; color:#aebccb}\n  .rep-name{font-size:18px; font-weight:700; margin-top:2px}\n  .rep-sair{height:44px; padding:0 18px; border:1px solid rgba(255,255,255,.35); background:transparent; color:#fff; border-radius:12px; font-size:14px; font-weight:600; cursor:pointer}\n  .rep-wrap{max-width:1100px; margin:0 auto; padding:20px}\n  .rep-h2{font-family:'Cormorant Garamond',Georgia,serif; font-size:26px; color:#2c2721; margin:4px 0 2px}\n  .rep-count{font-size:14px; color:#8a8073; font-weight:400; font-family:system-ui}\n  .rep-dica{font-size:13px; color:#8a8073; margin:2px 0 16px}\n  .rep-menu{display:grid; grid-template-columns:repeat(auto-fill, minmax(200px, 1fr)); gap:14px; margin-top:14px}\n  /* Home do rep: bloco de atalhos 3x2 à esquerda + área do painel/gráfico à direita */\n  .rep-home-layout{display:flex; gap:22px; align-items:stretch; margin-top:14px}\n  #repHome .rep-menu{flex:0 0 auto; grid-template-columns:repeat(3, minmax(160px,196px)); margin-top:0}\n  .rep-dash{flex:1 1 300px; min-width:0}\n  .rep-dash-ph{height:100%; min-height:258px; border:1.5px dashed #cdd6e2; border-radius:16px; display:flex; flex-direction:column; align-items:center; justify-content:center; color:#9aa3af; font-size:15px; font-weight:700; text-align:center; line-height:1.5}\n  .rep-dash-ph span{font-size:12.5px; font-weight:500}\n  .rep-dash-card{height:100%; min-height:258px; box-sizing:border-box; background:#fff; border:1px solid #DCE3EC; border-radius:16px; padding:15px 16px 12px; display:flex; flex-direction:column; box-shadow:0 2px 8px rgba(15,23,42,.05)}\n  .rdh{display:flex; align-items:baseline; justify-content:space-between; gap:8px}\n  .rdh-tit{font-weight:800; font-size:15px; color:#2c2721}\n  .rdh-sub{font-size:11.5px; color:#9aa3af}\n  .rdk{display:flex; gap:10px; margin:12px 0 2px}\n  .rdk-it{flex:1; min-width:0; background:#f4f7fb; border:1px solid #e6edf5; border-radius:11px; padding:9px 11px}\n  .rdk-lb{display:block; font-size:11px; color:#8a93a3; font-weight:600}\n  .rdk-vl{display:block; font-size:16px; font-weight:800; color:#1e4e8c; margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n  .rdc{flex:1 1 auto; min-height:118px; margin-top:10px; position:relative}\n  .rdc svg{display:block; max-width:100%}\n  .rd-bar{fill:#9db7d6}\n  .rd-bar.cur{fill:#1e6fd0}\n  .rd-bar:hover{fill:#1457a8; cursor:default}\n  .rd-xl{font-size:9.5px; fill:#9aa3af; font-weight:600}\n  .rd-empty{position:absolute; inset:0; display:flex; align-items:center; justify-content:center; color:#b4bccb; font-size:12.5px; text-align:center; line-height:1.5; padding:0 14px}\n  @media(max-width:900px){ .rep-home-layout{flex-direction:column} #repHome .rep-menu{grid-template-columns:repeat(3,minmax(0,1fr)); width:100%} .rep-dash{width:100%} }\n  @media(max-width:560px){ #repHome .rep-menu{grid-template-columns:1fr 1fr} }\n  .rep-tile{display:flex; flex-direction:column; align-items:flex-start; gap:4px; background:#fff; border:1px solid #DCE3EC; border-radius:16px; padding:20px 18px; cursor:pointer; box-shadow:0 2px 8px rgba(15,23,42,.05); font:inherit; text-align:left; min-height:120px; transition:box-shadow .15s ease, border-color .15s ease}\n  .rep-tile:hover{border-color:#cbd5e1; box-shadow:0 6px 16px rgba(15,23,42,.10)}\n  .rep-tile:active{transform:scale(.99)}\n  .rep-tile svg{width:30px; height:30px; stroke:#2c3e50; fill:none; stroke-width:1.8; stroke-linecap:round; stroke-linejoin:round; margin-bottom:6px}\n  .rep-tile .tl{font-weight:800; font-size:17px; color:#2c2721}\n  .rep-tile .tt{font-size:12.5px; color:#8a8073}\n  .rep-voltar{height:40px; padding:0 16px; border:1px solid #DCE3EC; background:#fff; color:#2c3e50; border-radius:10px; font-size:14px; font-weight:600; cursor:pointer; margin-bottom:10px}\n  .rep-grid{display:grid; grid-template-columns:repeat(auto-fill, minmax(280px, 1fr)); gap:12px}\n  .rep-card{display:block; width:100%; text-align:left; background:#fff; border:1px solid #DCE3EC; border-radius:14px; padding:16px; cursor:pointer; box-shadow:0 2px 8px rgba(15,23,42,.05); font:inherit}\n  .rep-card:active{transform:scale(.995)}\n  .rep-card .nm{font-weight:800; font-size:16px; color:#2c2721}\n  .rep-card .sub{font-size:13px; color:#8a8073; margin-top:3px}\n  .rep-chip{display:inline-flex; align-items:center; gap:6px; font-size:11.5px; font-weight:700; padding:3px 9px; border-radius:999px; margin-top:10px}\n  .rep-chip.ok{background:#dcfce7; color:#166534}\n  .rep-chip.wait{background:#fef9c3; color:#854d0e}\n  .rep-chip.block{background:#fee2e2; color:#991b1b}\n  .rep-chip.info{background:#dbeafe; color:#1e40af}\n  .rep-ped-acoes{display:flex; gap:8px; flex-wrap:wrap; margin-top:10px}\n  .rep-ped-acoes button{padding:9px 13px; border-radius:10px; font-size:13px; font-weight:600; cursor:pointer; border:1.5px solid #d6cfc2; background:#fff; color:#5f584e}\n  .rep-ped-acoes button.prim{border:0; background:#2c3e50; color:#fff}\n  .rep-ped-acoes button.go{border:0; background:#1f7a4d; color:#fff}\n  .rep-ped-acoes button.del{border:0; background:#fff; color:#b91c1c; border:1.5px solid #f3c6c6}\n  @media(max-width:560px){ .rep-grid{grid-template-columns:1fr} .rep-wrap{padding:16px} }\n  /* Minha carteira em LISTA: busca + linhas (nome, cnpj/cidade, último pedido, status) */\n  .rep-busca{display:flex; align-items:center; gap:9px; background:#fff; border:1px solid #DCE3EC; border-radius:12px; padding:0 14px; height:46px; max-width:520px; margin:4px 0 14px; box-shadow:0 1px 3px rgba(15,23,42,.05)}\n  .rep-busca svg{width:18px; height:18px; flex:0 0 auto; stroke:#8a8073; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round}\n  .rep-busca input{border:0; outline:0; background:transparent; width:100%; font:inherit; font-size:15px; color:#2c2721}\n  .rep-list{display:flex; flex-direction:column; gap:8px}\n  .rep-row{display:flex; align-items:center; gap:12px; width:100%; text-align:left; background:#fff; border:1px solid #DCE3EC; border-radius:12px; padding:13px 15px; cursor:pointer; box-shadow:0 1px 3px rgba(15,23,42,.04); font:inherit}\n  .rep-row:active{transform:scale(.997)}\n  .rep-row .ri{flex:1; min-width:0}\n  .rep-row .nm{font-weight:800; font-size:15.5px; color:#2c2721; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n  .rep-row .sub{font-size:12.5px; color:#8a8073; margin-top:2px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n  .rep-row .ped{font-size:12px; color:#6b7280; margin-top:4px; display:inline-flex; align-items:center; gap:5px}\n  .rep-row .ped svg{width:13px; height:13px; stroke:#9aa3af; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round}\n  .rep-row .rr{flex:0 0 auto; display:flex; align-items:center; gap:10px}\n  .rep-row .chev{width:18px; height:18px; stroke:#c0c7d1; fill:none; stroke-width:2.5; stroke-linecap:round; stroke-linejoin:round}\n  .rep-vazio{font-size:14px; color:#8a8073; padding:18px 2px}\n  @media(max-width:560px){ .rep-busca{max-width:none} .rep-row .sub,.rep-row .nm{white-space:normal} }\n  /* Meus pedidos — acordeão de cards fechados (status, nº, data, peças, valor, seta) */\n  .mp-card{background:#fff; border:1px solid #DCE3EC; border-radius:12px; margin-bottom:10px; box-shadow:0 1px 3px rgba(15,23,42,.05); overflow:hidden}\n  .mp-head{display:block; width:100%; text-align:left; background:transparent; border:0; cursor:pointer; padding:12px 14px; font:inherit; color:inherit}\n  .mp-l1{display:flex; align-items:center; gap:8px}\n  .mp-badge{display:inline-flex; align-items:center; gap:6px; font-size:12px; font-weight:700; padding:3px 9px; border-radius:999px; white-space:nowrap}\n  .mp-badge .dot{width:7px; height:7px; border-radius:50%; flex:0 0 auto}\n  .mp-badge.producao{background:#dcfce7; color:#166534} .mp-badge.producao .dot{background:#16a34a}\n  .mp-badge.separacao{background:#ffedd5; color:#9a3412} .mp-badge.separacao .dot{background:#ea580c}\n  .mp-badge.enviado{background:#dbeafe; color:#1e40af} .mp-badge.enviado .dot{background:#2563eb}\n  .mp-badge.entregue{background:#ede9fe; color:#5b21b6} .mp-badge.entregue .dot{background:#7c3aed}\n  .mp-badge.cancelado{background:#fee2e2; color:#991b1b} .mp-badge.cancelado .dot{background:#dc2626}\n  .mp-badge.processando,.mp-badge.recebido{background:#eef2f7; color:#475569} .mp-badge.processando .dot,.mp-badge.recebido .dot{background:#94a3b8}\n  .mp-num{font-weight:800; font-size:14px; color:var(--ink)}\n  .mp-chev{margin-left:auto; color:#94a3b8; display:flex; transition:transform .2s ease}\n  .mp-card.open .mp-chev{transform:rotate(180deg)}\n  .mp-chev svg{width:18px; height:18px; stroke:currentColor; fill:none; stroke-width:2; stroke-linecap:round; stroke-linejoin:round}\n  .mp-l2{display:flex; align-items:center; gap:10px; margin-top:7px; font-size:12.5px; color:var(--muted); flex-wrap:wrap}\n  .mp-l2 .mp-dt{color:var(--muted)}\n  .mp-l2 .mp-sep{opacity:.5}\n  .mp-l2 .mp-tot{margin-left:auto; font-weight:800; font-size:15px; color:var(--ink); white-space:nowrap}\n  .mp-body{display:none; padding:0 14px 12px; border-top:1px solid #eef2f7}\n  .mp-card.open .mp-body{display:block}\n  .mp-it{display:flex; align-items:baseline; gap:8px; padding:9px 0; font-size:13.5px; border-bottom:1px solid #f1f5f9}\n  .mp-it:last-child{border-bottom:0}\n  .mp-it .mp-nm{font-weight:600; color:var(--ink)}\n  .mp-it .mp-d{color:var(--muted); font-size:12.5px; flex:1 1 auto}\n  .mp-it .mp-q{font-weight:800; color:var(--ink); white-space:nowrap}\n  /* Nome do cliente no card (só na área do representante) — seminegrito, quebra se longo. */\n  .mp-cli{margin-top:6px; font-weight:600; font-size:14px; color:#2c2721; line-height:1.3; word-break:break-word}\n  .abas{display:none}\n  .cad-inp{width:100%; box-sizing:border-box; padding:11px 12px; border:1px solid #d6d0c4; border-radius:10px; font-size:15px; font-family:inherit; color:#2c2721}\n  .cad-inp:focus{outline:0; border-color:#ad5033}\n  /* categorias no centro — chips minimalistas (borda fina, fundo neutro, ícone SVG) */\n  /* barra que FIXA os ícones no topo (logo abaixo da busca) ao rolar */\n  .cats-bar{position:sticky; top:var(--cats-top,62px); z-index:30; background:var(--bg); border-bottom:1px solid #ece6db; box-shadow:0 6px 12px -10px rgba(44,39,33,.14)}\n  .cats{display:flex; justify-content:center; flex-wrap:wrap; gap:10px; max-width:960px; margin:0 auto; padding:12px 16px}\n  .cats button{display:inline-flex; align-items:center; gap:9px; padding:9px 17px; background:#fdfbf7; border:1px solid #e5dfd4; border-radius:11px; cursor:pointer; color:#6b6358; font-family:inherit; font-size:13px; font-weight:500; letter-spacing:.02em; line-height:1; transition:border-color .18s ease, color .18s ease, background .18s ease, box-shadow .18s ease}\n  .cats button svg{width:18px; height:18px; fill:none; stroke:#ae5033; stroke-width:1.6; opacity:.82; flex:0 0 auto; transition:opacity .18s ease}\n  .cats button:hover{border-color:#d4c6af; color:#2c2721; background:#fff; box-shadow:0 3px 12px rgba(44,39,33,.05)}\n  .cats button.on{border-color:#ae5033; color:#2c2721; background:#fbf2ec}\n  .cats button.on svg{opacity:1}\n  @media(max-width:560px){\n    /* Categorias: uma única linha, com rolagem horizontal suave (sem quebrar texto). */\n    .cats{gap:8px; margin:0 auto; padding:10px 12px; justify-content:flex-start; flex-wrap:nowrap; max-width:100%; overflow-x:auto; -webkit-overflow-scrolling:touch; scrollbar-width:none}\n    .cats::-webkit-scrollbar{display:none}\n    .cats button{width:auto; flex:0 0 auto; white-space:nowrap; padding:8px 14px; font-size:12px; gap:7px}\n    .cats button span{white-space:nowrap}\n    .cats button svg{width:15px; height:15px}\n    /* Título da seção não pode ficar escondido atrás das barras fixas ao rolar até ele. */\n    .sec{scroll-margin-top:calc(var(--cats-top,150px) + 56px)}\n  }\n  /* botão flutuante do WhatsApp */\n  .wa-float{position:fixed; right:18px; bottom:18px; z-index:900; width:56px; height:56px; border-radius:50%; background:#25d366; box-shadow:0 6px 20px rgba(0,0,0,.28); display:flex; align-items:center; justify-content:center; transition:transform .12s ease}\n  .wa-float:hover{transform:scale(1.07)}\n  .wa-float svg{width:30px; height:30px; fill:#fff}\n  @media(max-width:560px){ .cats .ci{width:54px; height:54px; font-size:23px} .wa-float{width:52px; height:52px; right:14px; bottom:14px} }\n  main{max-width:1760px; margin:0 auto; padding:18px 24px 70px}\n  .sec{margin-top:30px; scroll-margin-top:96px}\n  .sec h2{font-size:30px; margin:0; text-align:center; font-weight:600; color:var(--ink); display:flex; align-items:center; justify-content:center; gap:20px}\n  .sec h2::before,.sec h2::after{content:\"\"; height:1px; width:60px; background:var(--line)}\n  .sec .sub{text-align:center; color:var(--muted); font-size:12px; letter-spacing:.18em; text-transform:uppercase; margin-top:6px}\n  .grade{display:grid; grid-template-columns:repeat(2,1fr); gap:22px; margin-top:24px}\n  @media(min-width:700px){ .grade{grid-template-columns:repeat(3,1fr)} }\n  @media(min-width:1040px){ .grade{grid-template-columns:repeat(4,1fr)} }\n  @media(max-width:430px){ .grade{grid-template-columns:1fr} }\n  .prod{background:#fff; border:0; border-radius:var(--radius); overflow:hidden; box-shadow:var(--shadow); cursor:pointer; transition:transform .14s ease, box-shadow .14s ease}\n  .prod:hover{transform:translateY(-3px); box-shadow:0 2px 6px rgba(60,48,32,.08),0 18px 40px rgba(60,48,32,.12)}\n  .foto{position:relative; aspect-ratio:1/1; background:#efe7d8; overflow:hidden}\n  .foto img{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block; z-index:1}\n  .foto .ph{position:absolute; inset:0; z-index:0; display:flex; align-items:center; justify-content:center; font-family:\"Cormorant Garamond\",serif; font-size:34px; color:#c3b49a; letter-spacing:.06em}\n  .badge{position:absolute; left:12px; top:12px; font-size:11px; font-weight:600; padding:5px 11px; border-radius:999px; background:rgba(255,255,255,.95); color:#4f7a44; display:flex; align-items:center; gap:6px; z-index:2; box-shadow:0 1px 3px rgba(0,0,0,.08)}\n  .badge.off{color:#9c7b4a}\n  .badge .dot{width:7px; height:7px; border-radius:50%; background:currentColor}\n  .prod .info{padding:14px 16px 16px}\n  .prod .nome{font-weight:600; font-size:14px; color:var(--ink); line-height:1.3}\n  .preco{margin-top:7px; font-size:11.5px; color:var(--muted)}\n  .preco b{color:var(--accent); font-size:15px; font-weight:700; margin-left:2px}\n  .vazio{text-align:center; color:var(--muted); padding:60px 16px}\n  @media(max-width:760px){ .buscafaixa{min-height:0} .bf-in{display:flex; flex-direction:column; align-items:stretch; gap:10px} .bf-left{order:0; justify-content:space-between} .bf-logo{height:32px} .busca{grid-column:auto; justify-self:stretch; width:100%; max-width:none; order:1} .bf-right{grid-column:auto; justify-self:stretch; order:2; align-items:stretch; gap:6px} .bf-right-top{justify-content:flex-end; gap:10px} .saud{justify-content:flex-end; max-width:none} body.rep-mode .bf-voltar{justify-content:center} }\n  @media(max-width:640px){ .buscafaixa{padding:10px 16px} .banner{display:none} .banner .b-in{padding:0 20px} .banner .b-tit{font-size:30px} main{padding:14px 16px 60px} .sec{margin-top:24px} .sec h2{font-size:24px; gap:12px} .sec h2::before,.sec h2::after{width:34px} }\n  @media(max-width:420px){ .btn-ghost span,.btn-cart span:not(.n){display:none} .btn-ghost,.btn-cart{padding:0 12px} }\n  /* ---- popup \"continuar / escolher outro\" ao adicionar no carrinho ---- */\n  .popconf{position:fixed; inset:0; z-index:80; background:rgba(44,39,33,.55); display:flex; align-items:center; justify-content:center; padding:20px}\n  .popconf-box{background:var(--card); border-radius:16px; max-width:360px; width:100%; padding:24px 22px; text-align:center; box-shadow:0 20px 60px rgba(0,0,0,.3)}\n  .popconf-ic{font-size:34px}\n  .popconf-tit{font-weight:700; font-size:17px; margin-top:6px; color:var(--ink)}\n  .popconf-sub{color:var(--muted); font-size:13px; margin-top:4px}\n  .popconf-acts{display:flex; flex-direction:column; gap:9px; margin-top:16px}\n  .popconf-acts button{border-radius:10px; padding:12px; font-size:14px; font-weight:600; cursor:pointer; font-family:inherit}\n  .popconf-b1{background:var(--accent); color:#fff; border:0}\n  .popconf-b2{background:var(--card); color:var(--ink); border:1px solid var(--line)}\n  .popconf-cart{margin-top:12px; background:none; border:0; color:var(--muted); font-size:12.5px; cursor:pointer; text-decoration:underline; font-family:inherit}\n  /* ---- modal produto (largo, 2 colunas) ---- */\n  .modal{position:fixed; inset:0; z-index:60; background:rgba(44,39,33,.55); display:none}\n  .modal.show{display:block}\n  .sheet{position:absolute; inset:3% 2%; max-width:1500px; margin:0 auto; background:var(--card); border-radius:16px; overflow:hidden; display:flex; flex-direction:column; box-shadow:0 24px 70px rgba(0,0,0,.34)}\n  .sheet .topo{display:flex; justify-content:space-between; align-items:center; padding:12px 18px; border-bottom:1px solid var(--line); flex:0 0 auto}\n  .sheet .topo .lb{font-size:11px; letter-spacing:.16em; text-transform:uppercase; color:var(--muted); font-weight:600}\n  .sheet .fechar{border:0; background:var(--chip); width:34px; height:34px; border-radius:50%; font-size:16px; cursor:pointer; color:var(--ink)}\n  .det{flex:1 1 auto; display:flex; min-height:0}\n  .det .lado-foto{flex:1 1 53%; background:#efe7d8; position:relative; overflow:hidden}\n  .det .lado-foto img{position:absolute; inset:0; width:100%; height:100%; object-fit:cover; display:block; z-index:1}\n  .det .lado-foto .ph{position:absolute; inset:0; z-index:0; display:flex; align-items:center; justify-content:center; font-family:\"Cormorant Garamond\",serif; font-size:64px; color:#c3b49a}\n  .det .lado-info{flex:1 1 47%; overflow:auto; padding:0 28px 26px}\n  .det .linhalb{text-align:center; font-size:11px; letter-spacing:.16em; text-transform:uppercase; color:var(--muted); font-weight:600; margin-top:24px; margin-bottom:3px}\n  .det .nome{font-size:28px; margin:0 0 14px; font-weight:600; text-align:center; letter-spacing:.01em; line-height:1.1}\n  .vid{width:100%; border-radius:12px; background:#000; margin-bottom:12px; max-height:300px}\n  .comp{text-align:center; color:var(--muted); font-size:13px; letter-spacing:.04em}\n  .prazo{display:flex; gap:8px; align-items:center; background:#f6efe3; border:1px solid var(--line); border-radius:12px; padding:10px 14px; font-size:13px; color:var(--ink); margin:14px 0}\n  .bloco{margin-top:14px}\n  .bloco h5{margin:0 0 5px; font-size:11px; letter-spacing:.12em; text-transform:uppercase; color:var(--muted)}\n  .bloco ul{margin:0; padding-left:18px; font-size:14px}\n  .bloco li{margin:2px 0}\n  .montar{margin-top:22px; border-top:1px solid var(--line); padding-top:18px}\n  .montar h4{display:flex; align-items:center; gap:8px; font-size:17px; margin:0 0 14px}\n  .lbl{font-size:11px; letter-spacing:.12em; text-transform:uppercase; color:var(--muted); font-weight:600; margin:16px 0 8px}\n  .lbl b{color:var(--ink); text-transform:none; letter-spacing:0; font-weight:600}\n  .lbl .cnt{color:#7a7068; font-weight:400; text-transform:none; letter-spacing:0; font-size:12px}\n  .cores{display:flex; flex-wrap:wrap; gap:11px; align-items:center}\n  /* trava a escolha de cor no topo enquanto os tamanhos rolam */\n  .cor-sticky{position:sticky; top:0; z-index:8; background:var(--card); padding:14px 0 10px; box-shadow:0 10px 10px -10px rgba(0,0,0,.14)}\n  .sw-dot{position:relative; width:36px; height:36px; border-radius:50%; padding:0; outline:0; cursor:pointer; background:#efe7d8 center/cover no-repeat; border:2px solid #fff; box-shadow:0 0 0 1px var(--line); transition:transform .1s ease, box-shadow .1s ease}\n  .sw-dot:hover{transform:scale(1.09); box-shadow:0 0 0 1px #cabfa9}\n  .sw-dot.on{border-color:#fff; box-shadow:0 0 0 2px #ae5033}\n  .sw-dot.has{box-shadow:0 0 0 2px #ae5033}\n  .sw-n{position:absolute; top:-6px; right:-6px; min-width:17px; height:17px; padding:0 4px; border-radius:9px; background:#ae5033; color:#fff; font-size:10px; font-weight:700; line-height:17px; text-align:center; box-shadow:0 0 0 1.5px #fff; pointer-events:none}\n  .corfoto{margin-top:10px; display:flex; flex-direction:row; align-items:center; gap:12px}\n  .corfoto .cf-img{width:75px; height:75px; border-radius:10px; background:#efe7d8; object-fit:cover; border:1px solid var(--line); flex:0 0 auto}\n  .corfoto img.cf-img{cursor:zoom-in}\n  .corfoto .cf-nm{font-weight:600; font-size:14px; color:var(--ink)}\n  .corfoto .cf-amp{font-size:11.5px; color:var(--muted); margin-top:2px}\n  /* ---- lightbox: foto da cor ampliada ---- */\n  .lightbox{position:fixed; inset:0; z-index:90; background:rgba(20,16,12,.9); display:flex; align-items:center; justify-content:center; padding:24px; cursor:zoom-out}\n  .lightbox img{max-width:min(94vw,1100px); max-height:92vh; border-radius:12px; box-shadow:0 20px 70px rgba(0,0,0,.5)}\n  .lightbox .cap{position:fixed; left:0; right:0; bottom:20px; text-align:center; color:#fff; font-size:15px; font-weight:600; text-shadow:0 1px 4px rgba(0,0,0,.6)}\n  .lb-x{position:fixed; top:16px; right:20px; background:rgba(255,255,255,.16); color:#fff; border:0; border-radius:50%; width:42px; height:42px; font-size:18px; cursor:pointer}\n  .grp{margin-top:16px}\n  .grp{margin-bottom:4px}\n  .grp .t{color:var(--accent); font-weight:600; font-size:15px; margin:14px 0 2px; letter-spacing:.01em}\n  .grp:first-child .t{margin-top:4px}\n  .tamrow{display:flex; align-items:center; justify-content:space-between; gap:10px; padding:11px 0; border-bottom:1px solid var(--line)}\n  .tamrow .medbox{flex:1 1 auto; min-width:0}\n  .tamrow .med{font-size:15px; color:var(--ink); font-weight:500; line-height:1.3}\n  .tamrow .med small{color:var(--muted); margin-left:6px}\n  .tamrow .estx{font-size:12.5px; color:#6f685e; margin-top:3px}\n  .tamrow .estx.low{color:var(--accent); font-weight:600}\n  .tamrow .estx.off{color:#9aa0ab}\n  .tamrow .pr{flex:0 0 auto; min-width:92px; text-align:right; color:var(--ink); font-weight:600; font-size:14px; font-family:'Montserrat',sans-serif; margin-left:auto; margin-right:10px; white-space:nowrap; line-height:1.3}\n  .tamrow .stepper{flex:0 0 auto}\n  .stepper{display:flex; align-items:center; gap:0; border:1px solid var(--line); border-radius:999px; overflow:hidden}\n  .stepper button{border:0; background:var(--chip); width:30px; height:30px; font-size:17px; cursor:pointer; color:var(--ink)}\n  .stepper input{width:40px; border:0; text-align:center; font-size:14px; background:transparent; outline:0; -moz-appearance:textfield}\n  .stepper input::-webkit-outer-spin-button,.stepper input::-webkit-inner-spin-button{-webkit-appearance:none}\n  .resumo{display:flex; align-items:center; justify-content:space-between; gap:10px; margin-top:16px; padding:12px 16px; background:#faf6ef; border:1px solid var(--line); border-radius:10px}\n  .resumo .rz-q{font-size:13.5px; color:var(--muted)}\n  .resumo .rz-v{font-size:19px; font-weight:700; color:var(--ink); font-family:'Montserrat',sans-serif}\n  .addcart{position:sticky; bottom:0; margin-top:10px; width:100%; min-height:46px; border:0; background:#ae5033; color:#fff; border-radius:10px; padding:12px 15px; font-size:15px; font-weight:600; letter-spacing:.01em; cursor:pointer; display:flex; align-items:center; justify-content:center; gap:8px}\n  .addcart:disabled{background:#cdbfa8; cursor:default}\n  @media(max-width:860px){ .det{flex-direction:column; overflow:auto} .det .lado-foto{flex:0 0 auto; aspect-ratio:4/3} .det .lado-info{overflow:visible} .sheet{inset:0; border-radius:0; max-width:none} }\n  /* CELULAR: cada tamanho em 2 linhas — descrição (quebra) em cima; preço à esquerda e\n     o controle de quantidade à direita embaixo. Botões 44×44, o controle nunca encolhe. */\n  @media(max-width:560px){\n    .det .lado-info{padding:0 16px 24px}\n    .tamrow{flex-wrap:wrap; align-items:center; column-gap:10px; row-gap:6px}\n    .tamrow .medbox{flex:1 1 100%; min-width:0}\n    .tamrow .med{min-width:0; word-break:break-word}\n    .tamrow .pr{margin-left:0; margin-right:auto; font-size:15px}\n    .tamrow .stepper{flex:0 0 auto}\n    .stepper button{width:44px; height:44px; font-size:20px}\n    .stepper input{width:48px; height:44px; font-size:16px}\n  }\n  /* ---- carrinho (gaveta) ---- */\n  .cart{position:fixed; inset:0; z-index:70; background:rgba(44,39,33,.5); display:none}\n  .cart.show{display:block}\n  /* Janela ~55% da tela no desktop; abre pela direita; responsiva no tablet/celular. */\n  .cart .pane{position:absolute; top:0; right:0; bottom:0; width:55vw; max-width:980px; min-width:460px; background:var(--bg); display:flex; flex-direction:column; box-shadow:-10px 0 40px rgba(0,0,0,.2)}\n  /* Cabeçalho FIXO (título 15px + cliente 12px + total de itens). */\n  .cart .ctopo{flex:0 0 auto; display:flex; justify-content:space-between; align-items:flex-start; gap:10px; padding:10px 16px; border-bottom:1px solid var(--line); background:var(--card)}\n  .cart .ctopo .ctit{min-width:0}\n  .cart .ctopo h3{margin:0; font-size:15px; font-weight:700}\n  .cart .ctopo .csub{font-size:12px; color:var(--muted); margin-top:1px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n  .cart .ctopo .csub b{color:var(--ink); font-weight:700}\n  /* Lista de itens: SÓ ela rola; o cabeçalho da tabela fica grudado no topo. */\n  .cart .itens{flex:1 1 auto; overflow-y:auto; padding:0; -webkit-overflow-scrolling:touch}\n  .ctbl{width:100%; border-collapse:collapse; table-layout:fixed}\n  .ctbl thead th{position:sticky; top:0; z-index:1; background:var(--card); text-align:left; font-size:11px; font-weight:700; color:var(--muted); text-transform:uppercase; letter-spacing:.02em; padding:7px 10px; border-bottom:1px solid var(--line)}\n  .ctbl td{padding:8px 10px; border-bottom:1px solid var(--line); font-size:12px; vertical-align:top}\n  .ctbl tbody tr:nth-child(even){background:var(--bg-soft,#faf8f4)}\n  .ctbl .c-prod{font-weight:700; color:var(--ink); width:140px; white-space:normal; word-break:break-word; line-height:1.3}\n  .ctbl .c-desc{font-size:11px; color:var(--muted); white-space:normal; word-break:break-word; line-height:1.4}\n  .ctbl th.c-qtd{width:104px; text-align:center} .ctbl td.c-qtd{text-align:center}\n  .ctbl th.c-val{width:92px; text-align:right} .ctbl td.c-val{text-align:right; font-weight:700; font-family:'Montserrat',sans-serif; color:var(--ink); white-space:nowrap}\n  .ctbl th.c-rm{width:34px} .ctbl td.c-rm{text-align:center}\n  .ctbl td.c-rm button{border:0; background:transparent; color:#b23b30; cursor:pointer; font-size:13px; padding:2px; opacity:.7; line-height:1}\n  .ctbl td.c-rm button:hover{opacity:1}\n  .stepper.mini{display:inline-flex; border:1px solid var(--line); border-radius:7px}\n  .stepper.mini button{width:24px; height:24px; font-size:14px}\n  .stepper.mini input{width:28px; height:24px; font-size:12px}\n  /* Rodapé FIXO (total 16px + forma + obs + ações), bem compacto. */\n  .cfoot{flex:0 0 auto; border-top:1px solid var(--line); background:var(--card); padding:10px 16px}\n  .cfoot .tot{display:flex; justify-content:space-between; align-items:baseline; font-size:13px; margin-bottom:8px}\n  .cfoot .tot b{font-family:'Montserrat',sans-serif; color:var(--ink); font-size:16px; font-weight:700}\n  .cfoot .fin{width:100%; border:0; background:var(--accent); color:#fff; border-radius:9px; padding:11px; font-size:14px; font-weight:600; cursor:pointer}\n  .cart-inp{font-size:13px !important; padding:8px 10px !important}\n  .cvazio{text-align:center; color:var(--muted); padding:40px 16px; font-size:13px}\n  /* Meus pedidos do rep — acordeão (um pedido detalhado por vez) + tabela de itens. */\n  .rped{border:1px solid #DCE3EC; border-radius:12px; margin-bottom:8px; background:#fff; overflow:hidden}\n  .rped.open{box-shadow:0 2px 10px rgba(15,23,42,.06)}\n  .rped-h{display:flex; align-items:center; gap:10px; width:100%; text-align:left; background:transparent; border:0; padding:11px 14px; cursor:pointer; font:inherit}\n  .rped-hi{flex:1; min-width:0}\n  .rped-cli{display:block; font-weight:800; font-size:14px; color:#2c2721; white-space:nowrap; overflow:hidden; text-overflow:ellipsis}\n  .rped-res{display:block; font-size:12px; color:#8a8073; margin-top:2px}\n  .rped-chev{flex:0 0 auto; color:#c0c7d1; transition:transform .15s}\n  .rped.open .rped-chev{transform:rotate(180deg)}\n  .rped-det{display:none}\n  .rped.open .rped-det{display:block; border-top:1px solid #eef0f3}\n  .rped-body{padding:10px 12px}\n  .rped-grid{display:grid; grid-template-columns:repeat(auto-fit,minmax(118px,1fr)); gap:8px 14px; margin-bottom:10px}\n  .rped-grid > div{display:flex; flex-direction:column; gap:3px; align-items:flex-start}\n  .rped-grid span{font-size:10px; font-weight:700; color:#9aa3af; text-transform:uppercase; letter-spacing:.03em}\n  .rped-grid b{font-size:13px; color:#2c2721}\n  .rped-grid .rped-tot{font-size:15px; color:#1f7a4d; font-weight:800}\n  .pedtbl{border:1px solid #eef0f3; border-radius:8px; overflow:hidden; margin-bottom:10px}\n  .pedtbl th.c-qtd, .pedtbl td.c-qtd{width:52px; text-align:center}\n  .pedtbl th.c-val, .pedtbl td.c-val{width:84px}\n  .pedtbl td{background:#fff}\n  .pedtbl tbody tr:nth-child(even) td{background:#faf8f4}\n  @media(max-width:900px){ .cart .pane{width:74vw} }\n  @media(max-width:600px){ .cart .pane{width:100%; min-width:0; max-width:none} }\n  footer{text-align:center; color:var(--muted); font-size:12px; padding:30px 16px 50px; border-top:1px solid var(--line)}\n  footer .nm{font-family:\"Cormorant Garamond\",serif; font-size:16px; color:var(--ink)}\n  footer .obs{font-size:11px; margin-top:8px; opacity:.85}\n</style>\n</head>\n<body>\n<script>try{if(new URLSearchParams(location.search).get(\"rep\")===\"1\")document.documentElement.classList.add(\"portal-rep\");}catch(e){}</script>\n<div id=\"repBoot\" class=\"rep-boot\"><div class=\"rep-boot-in\"><div class=\"rep-boot-sp\"></div>Abrindo área do representante…</div></div>\n<section class=\"banner\" id=\"banner\"></section>\n\n<div class=\"buscafaixa\">\n  <div class=\"bf-in\">\n    <div class=\"bf-left\">\n      <button class=\"bf-voltar\" id=\"repVoltarCat\" onclick=\"__repVoltarArea()\" type=\"button\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m15 18-6-6 6-6\"/></svg>Voltar</button>\n      <img class=\"bf-logo\" src=\"/logo-bt-mark.png\" alt=\"Big Tricot Home Decor\">\n    </div>\n    <label class=\"busca\"><svg class=\"bf-ico\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.3-4.3\"/></svg><input id=\"q\" name=\"busca-catalogo\" placeholder=\"Buscar produto, cor ou referência…\" autocomplete=\"off\" autocorrect=\"off\" autocapitalize=\"off\" spellcheck=\"false\" data-form-type=\"other\" readonly onfocus=\"this.removeAttribute('readonly')\"></label>\n    <div class=\"bf-right\">\n      <div class=\"bf-right-top\">\n        <button class=\"btn-ghost\" id=\"abrirMeus\" title=\"Meus pedidos\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z\"/><path d=\"m3.3 7 8.7 5 8.7-5\"/><path d=\"M12 22V12\"/></svg><span>Meus pedidos</span></button>\n        <button class=\"btn-cart\" id=\"abrirCart\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"21\" r=\"1\"/><circle cx=\"19\" cy=\"21\" r=\"1\"/><path d=\"M2.5 2.5h2l2.6 12.4a2 2 0 0 0 2 1.6h9.3a2 2 0 0 0 2-1.6L23 6H6\"/></svg><span>Carrinho</span> <span class=\"n\" id=\"cartN\">0</span></button>\n      </div>\n      <span id=\"saudacao\" class=\"saud\" style=\"display:none\"></span>\n    </div>\n  </div>\n</div>\n<nav class=\"abas\" id=\"abas\"></nav>\n\n<div class=\"cats-bar\" id=\"catsBar\" style=\"display:none\"><div class=\"cats\" id=\"cats\"></div></div>\n\n<div id=\"avisoLib\" style=\"display:none;background:#fbf0e3;border-bottom:1px solid #eadcc6;color:#8a5a2b;font-size:13px;line-height:1.4;padding:10px 16px;text-align:center\"></div>\n<main id=\"app\"><div class=\"vazio\">Carregando catálogo…</div></main>\n\n<a id=\"waFloat\" class=\"wa-float\" href=\"#\" target=\"_blank\" rel=\"noopener\" style=\"display:none\" aria-label=\"Falar no WhatsApp\" title=\"Falar no WhatsApp\">\n  <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"M.057 24l1.687-6.163a11.867 11.867 0 01-1.587-5.945C.16 5.335 5.495 0 12.05 0a11.817 11.817 0 018.413 3.488 11.824 11.824 0 013.48 8.414c-.003 6.557-5.338 11.892-11.893 11.892a11.9 11.9 0 01-5.688-1.448L.057 24zm6.597-3.807c1.676.995 3.276 1.591 5.392 1.592 5.448 0 9.886-4.434 9.889-9.885.002-5.462-4.415-9.89-9.881-9.892-5.452 0-9.887 4.434-9.889 9.884a9.82 9.82 0 001.517 5.248l-.999 3.648 3.971-1.015zm11.387-5.464c-.074-.124-.272-.198-.57-.347-.297-.149-1.758-.868-2.031-.967-.272-.099-.47-.149-.669.149-.198.297-.768.967-.941 1.165-.173.198-.347.223-.644.074-.297-.149-1.255-.462-2.39-1.475-.883-.788-1.48-1.761-1.653-2.059-.173-.297-.018-.458.13-.606.134-.133.297-.347.446-.52.149-.174.198-.298.297-.496.099-.198.05-.372-.025-.521-.074-.149-.669-1.612-.916-2.207-.242-.579-.487-.5-.669-.51l-.57-.01c-.198 0-.52.074-.792.372s-1.04 1.016-1.04 2.479 1.065 2.876 1.213 3.074c.149.198 2.095 3.2 5.076 4.487.709.306 1.263.489 1.694.626.712.226 1.36.194 1.872.118.571-.085 1.758-.719 2.006-1.413.248-.695.248-1.29.173-1.414z\"/></svg>\n</a>\n\n<footer>\n  <div class=\"nm\">Big Tricot</div>\n  Monte Sião · MG<br>\n  <span id=\"rodape\"></span>\n  <div class=\"obs\">Preços e estoque do Syntech. Fotos e descrições do catálogo Big Tricot.</div>\n</footer>\n\n<div class=\"modal\" id=\"modal\"><div class=\"sheet\" id=\"sheet\"></div></div>\n<div class=\"cart\" id=\"cart\"><div class=\"pane\" id=\"cartPane\"></div></div>\n<div class=\"cart\" id=\"meus\"><div class=\"pane\" id=\"meusPane\"></div></div>\n\n<!-- ÁREA DO REPRESENTANTE (R1): carteira dele -->\n<div id=\"repArea\" style=\"display:none\">\n  <div class=\"rep-top\">\n    <div><div class=\"rep-hello\">Área do Representante</div><div class=\"rep-name\" id=\"repNome\"></div></div>\n    <button id=\"repSair\" class=\"rep-sair\">Sair</button>\n  </div>\n  <div class=\"rep-wrap\">\n    <!-- Tela inicial: menu de opções -->\n    <div id=\"repHome\">\n      <h2 class=\"rep-h2\">Olá, <span id=\"repOla\"></span> 👋</h2>\n      <div class=\"rep-dica\">O que você quer fazer hoje?</div>\n      <div class=\"rep-home-layout\">\n        <div class=\"rep-menu\">\n          <button class=\"rep-tile\" onclick=\"__repSecao('carteira')\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/><path d=\"M16 3.13a4 4 0 0 1 0 7.75\"/></svg>\n            <span class=\"tl\">Minha carteira</span><span class=\"tt\" id=\"repTileCount\">clientes</span>\n          </button>\n          <button class=\"rep-tile\" onclick=\"__repSecao('montar')\">\n            <svg viewBox=\"0 0 24 24\"><circle cx=\"8\" cy=\"21\" r=\"1\"/><circle cx=\"19\" cy=\"21\" r=\"1\"/><path d=\"M2.5 2.5h2l2.6 12.4a2 2 0 0 0 2 1.6h9.3a2 2 0 0 0 2-1.6L23 6H6\"/></svg>\n            <span class=\"tl\">Novo pedido</span><span class=\"tt\">começar agora</span>\n          </button>\n          <button class=\"rep-tile\" onclick=\"__repSecao('produtos')\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z\"/><path d=\"m3.3 7 8.7 5 8.7-5\"/><path d=\"M12 22V12\"/></svg>\n            <span class=\"tl\">Produtos</span><span class=\"tt\">ver catálogo</span>\n          </button>\n          <button class=\"rep-tile\" onclick=\"__repSecao('avisos')\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M6 8a6 6 0 0 1 12 0c0 7 3 9 3 9H3s3-2 3-9\"/><path d=\"M10.3 21a1.94 1.94 0 0 0 3.4 0\"/></svg>\n            <span class=\"tl\">Avisos</span><span class=\"tt\">recados</span>\n          </button>\n          <button class=\"rep-tile\" onclick=\"__repSecao('pedidos')\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z\"/><path d=\"M14 2v6h6\"/><path d=\"M8 13h8\"/><path d=\"M8 17h8\"/></svg>\n            <span class=\"tl\">Meus pedidos</span><span class=\"tt\">acompanhar</span>\n          </button>\n          <button class=\"rep-tile\" onclick=\"__repSecao('novo')\">\n            <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M19 8v6\"/><path d=\"M22 11h-6\"/></svg>\n            <span class=\"tl\">Novo cliente</span><span class=\"tt\">cadastrar</span>\n          </button>\n        </div>\n        <!-- Mini painel de vendas do representante (últimos 6 meses) -->\n        <div class=\"rep-dash\" id=\"repDash\">\n          <div class=\"rep-dash-card\">\n            <div class=\"rdh\"><div class=\"rdh-tit\">Minhas vendas</div><div class=\"rdh-sub\">últimos 6 meses</div></div>\n            <div class=\"rdk\">\n              <div class=\"rdk-it\"><span class=\"rdk-lb\">Vendas do mês</span><span class=\"rdk-vl\" id=\"rdVendaMes\">R$ 0,00</span></div>\n              <div class=\"rdk-it\"><span class=\"rdk-lb\">Pedidos no mês</span><span class=\"rdk-vl\" id=\"rdPedMes\">0</span></div>\n            </div>\n            <div class=\"rdc\" id=\"rdChart\"><div class=\"rd-empty\">Carregando…</div></div>\n          </div>\n        </div>\n      </div>\n    </div>\n    <!-- Sub-tela: carteira -->\n    <div id=\"repCartView\" style=\"display:none\">\n      <button class=\"rep-voltar\" onclick=\"__repHome()\">← Voltar</button>\n      <h2 class=\"rep-h2\" id=\"repCartTit\">Minha carteira <span class=\"rep-count\" id=\"repCount\"></span></h2>\n      <div class=\"rep-dica\" id=\"repCartDica\">Toque num cliente para atender.</div>\n      <label class=\"rep-busca\"><svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.3-4.3\"/></svg><input id=\"repBusca\" type=\"text\" placeholder=\"Buscar cliente por nome, CNPJ ou cidade…\" autocomplete=\"off\" autocapitalize=\"off\" spellcheck=\"false\"></label>\n      <div id=\"repCarteira\" class=\"rep-list\"></div>\n    </div>\n    <!-- Sub-tela: montar pedido (1º passo) -->\n    <div id=\"repMontar\" style=\"display:none\">\n      <button class=\"rep-voltar\" onclick=\"__repHome()\">← Voltar</button>\n      <h2 class=\"rep-h2\">Novo pedido</h2>\n      <div class=\"rep-dica\">Primeiro, escolha pra quem é o pedido:</div>\n      <div class=\"rep-menu\">\n        <button class=\"rep-tile\" onclick=\"__repEscolher()\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M22 21v-2a4 4 0 0 0-3-3.87\"/></svg>\n          <span class=\"tl\">Cliente da carteira</span><span class=\"tt\">escolher um que já é meu</span>\n        </button>\n        <button class=\"rep-tile\" onclick=\"__repSecao('novo')\">\n          <svg viewBox=\"0 0 24 24\"><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2\"/><circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M19 8v6\"/><path d=\"M22 11h-6\"/></svg>\n          <span class=\"tl\">Cliente novo</span><span class=\"tt\">cadastrar agora</span>\n        </button>\n      </div>\n    </div>\n    <!-- Sub-tela: meus pedidos (do representante) -->\n    <div id=\"repPedidos\" style=\"display:none\">\n      <button class=\"rep-voltar\" onclick=\"__repHome()\">← Voltar</button>\n      <h2 class=\"rep-h2\">Meus pedidos</h2>\n      <div class=\"rep-dica\">Pedidos em espera e enviados. Toque num <b>em espera</b> pra gerar o PDF ou enviar à Big.</div>\n      <div id=\"repPedLista\" class=\"rep-list\"></div>\n    </div>\n    <!-- Sub-tela: cadastrar cliente novo (pelo rep) -->\n    <div id=\"repNovoCli\" style=\"display:none\">\n      <button class=\"rep-voltar\" onclick=\"__repHome()\">← Voltar</button>\n      <h2 class=\"rep-h2\">Cadastrar cliente novo</h2>\n      <div class=\"rep-dica\">Digite o CNPJ e toque em <b>Buscar</b> pra preencher pela Receita. Assim que cadastrar, já pode montar o pedido. (* obrigatório)</div>\n      <div id=\"rncMsg\" style=\"font-size:13px;min-height:1px;margin:6px 0;line-height:1.35\"></div>\n      <div style=\"display:grid;gap:10px;max-width:560px\">\n        <div style=\"display:flex;gap:8px\">\n          <input id=\"rnCnpj\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"CNPJ *\" style=\"flex:1\">\n          <button type=\"button\" id=\"rnReceita\" style=\"flex:0 0 auto;display:inline-flex;align-items:center;gap:7px;padding:0 16px;border:0;border-radius:12px;background:#3b6ea5;color:#fff;font-size:14px;font-weight:600;cursor:pointer;white-space:nowrap\"><svg viewBox=\"0 0 24 24\" width=\"17\" height=\"17\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"8\"/><path d=\"m21 21-4.3-4.3\"/></svg><span id=\"rnRecLbl\">Buscar</span></button>\n        </div>\n        <input id=\"rnNome\" class=\"cad-inp\" placeholder=\"Razão social *\" autocomplete=\"organization\">\n        <input id=\"rnFant\" class=\"cad-inp\" placeholder=\"Nome fantasia *\">\n        <div style=\"display:flex;gap:8px;align-items:center\">\n          <input id=\"rnIe\" class=\"cad-inp\" placeholder=\"Inscrição estadual *\" style=\"flex:1\">\n          <label style=\"display:flex;align-items:center;gap:6px;font-size:13.5px;color:#5f584e;white-space:nowrap;cursor:pointer\"><input type=\"checkbox\" id=\"rnIsento\" style=\"width:18px;height:18px\"> Isento</label>\n        </div>\n        <input id=\"rnEnd\" class=\"cad-inp\" placeholder=\"Endereço (rua) *\">\n        <div style=\"display:flex;gap:8px\"><input id=\"rnNum\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"Nº\" style=\"flex:0 0 90px\"><input id=\"rnBai\" class=\"cad-inp\" placeholder=\"Bairro\" style=\"flex:1\"></div>\n        <div style=\"display:flex;gap:8px\"><input id=\"rnCep\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"CEP\" style=\"flex:1\"><input id=\"rnCid\" class=\"cad-inp\" placeholder=\"Cidade *\" style=\"flex:2\"><select id=\"rnUf\" class=\"cad-inp\" style=\"flex:0 0 86px\"><option value=\"\">UF *</option><option>AC</option><option>AL</option><option>AP</option><option>AM</option><option>BA</option><option>CE</option><option>DF</option><option>ES</option><option>GO</option><option>MA</option><option>MT</option><option>MS</option><option>MG</option><option>PA</option><option>PB</option><option>PR</option><option>PE</option><option>PI</option><option>RJ</option><option>RN</option><option>RS</option><option>RO</option><option>RR</option><option>SC</option><option>SP</option><option>SE</option><option>TO</option></select></div>\n        <input id=\"rnTel\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"WhatsApp *\">\n        <input id=\"rnEmail\" class=\"cad-inp\" type=\"email\" placeholder=\"E-mail * (confira se é atual!)\">\n        <button id=\"rnBtn\" style=\"padding:14px;border:0;border-radius:12px;background:#2c3e50;color:#fff;font-size:16px;font-weight:600;cursor:pointer\">Enviar cadastro</button>\n      </div>\n    </div>\n    <!-- Sub-tela: cadastro concluído (cliente já liberado, pode seguir com o pedido) -->\n    <div id=\"repNovoOk\" style=\"display:none\">\n      <div style=\"max-width:460px;margin:8px auto;text-align:center;padding:10px\">\n        <div style=\"width:72px;height:72px;margin:0 auto 14px;border-radius:50%;background:#dcfce7;display:flex;align-items:center;justify-content:center\">\n          <svg viewBox=\"0 0 24 24\" width=\"38\" height=\"38\" fill=\"none\" stroke=\"#166534\" stroke-width=\"2.5\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><path d=\"M20 6 9 17l-5-5\"/></svg>\n        </div>\n        <h2 class=\"rep-h2\" style=\"justify-content:center\">Cliente cadastrado! 🎉</h2>\n        <div class=\"rep-dica\" style=\"text-align:center\"><b id=\"repOkNome\"></b> já está liberado.<br>Pode montar o pedido agora.</div>\n        <div style=\"display:grid;gap:10px;margin-top:18px\">\n          <button id=\"repOkPedido\" style=\"padding:15px;border:0;border-radius:12px;background:#2c3e50;color:#fff;font-size:16px;font-weight:600;cursor:pointer;display:inline-flex;align-items:center;justify-content:center;gap:9px\"><svg viewBox=\"0 0 24 24\" width=\"19\" height=\"19\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\"><circle cx=\"8\" cy=\"21\" r=\"1\"/><circle cx=\"19\" cy=\"21\" r=\"1\"/><path d=\"M2.5 2.5h2l2.6 12.4a2 2 0 0 0 2 1.6h9.3a2 2 0 0 0 2-1.6L23 6H6\"/></svg>Novo pedido</button>\n          <button id=\"repOkFechar\" style=\"padding:13px;border:1.5px solid #d6cfc2;border-radius:12px;background:#fff;color:#5f584e;font-size:15px;font-weight:600;cursor:pointer\">Fechar</button>\n        </div>\n      </div>\n    </div>\n  </div>\n</div>\n<!-- Faixa no topo do catálogo quando o REP está montando pedido pra um cliente -->\n<div id=\"repPedBar\" style=\"display:none;position:sticky;top:0;z-index:45;background:#2c3e50;color:#fff;padding:10px 16px;display:none;align-items:center;gap:12px;justify-content:center;font-size:13.5px\">\n  <span>🧑‍💼 Montando pedido para <b id=\"repPedNome\"></b></span>\n  <button onclick=\"__repVoltarArea()\" style=\"height:32px;padding:0 12px;border:1px solid rgba(255,255,255,.4);background:transparent;color:#fff;border-radius:8px;font-size:12.5px;font-weight:600;cursor:pointer\">← Voltar</button>\n</div>\n\n<div id=\"entrada\" style=\"position:fixed;inset:0;z-index:999;background:rgba(44,39,33,.55);backdrop-filter:blur(3px);display:none;align-items:center;justify-content:center;padding:18px\">\n  <div style=\"background:#fff;border-radius:18px;max-width:420px;width:100%;box-shadow:0 20px 60px rgba(0,0,0,.25);overflow:hidden;position:relative\">\n    <button type=\"button\" id=\"entFechar\" aria-label=\"Fechar e ver o catálogo\" title=\"Fechar\" style=\"position:absolute;top:10px;right:10px;z-index:2;width:34px;height:34px;border:0;border-radius:50%;background:#f1ece3;color:#6b6358;font-size:16px;line-height:1;cursor:pointer;display:none;align-items:center;justify-content:center\">✕</button>\n    <div style=\"padding:26px 24px 8px;text-align:center\">\n      <div style=\"font-family:'Cormorant Garamond',Georgia,serif;font-size:26px;font-weight:700;letter-spacing:.02em;color:#2c2721\">BIG TRICOT</div>\n      <div style=\"font-size:12px;letter-spacing:.14em;text-transform:uppercase;color:#ad5033;margin-top:2px\">Catálogo de atacado</div>\n    </div>\n    <div style=\"padding:14px 24px 24px\">\n      <div id=\"entView\">\n        <label style=\"display:block;font-size:14px;color:#5f584e;margin-bottom:6px\">Entre com o CNPJ e a senha da sua loja</label>\n        <input id=\"entCnpj\" type=\"text\" inputmode=\"numeric\" autocomplete=\"username\" placeholder=\"CNPJ\" style=\"display:block;width:100%;box-sizing:border-box;padding:13px;border:1px solid #d6d0c4;border-radius:12px;font-size:16px\">\n        <input id=\"entSenha\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Senha\" style=\"display:block;width:100%;box-sizing:border-box;padding:13px;border:1px solid #d6d0c4;border-radius:12px;font-size:16px;margin-top:8px\">\n        <div id=\"entMsg\" style=\"font-size:13px;min-height:1px;margin:8px 0;line-height:1.35\"></div>\n        <button id=\"entBtn\" style=\"width:100%;padding:14px;border:0;border-radius:12px;background:#ad5033;color:#fff;font-size:16px;font-weight:600;cursor:pointer\">Entrar</button>\n        <div style=\"text-align:center;margin-top:14px;font-size:13.5px;color:#5f584e\">Ainda não é cliente?<br><button type=\"button\" id=\"irCad\" style=\"margin-top:4px;background:none;border:0;color:#ad5033;font-weight:700;font-size:14px;cursor:pointer;text-decoration:underline\">Cadastrar minha loja</button></div>\n        <div style=\"text-align:center;margin-top:12px;padding-top:12px;border-top:1px solid #efe9de;font-size:13px;color:#8a8073\">É representante?<br><button type=\"button\" id=\"irRep\" style=\"margin-top:4px;background:none;border:0;color:#5f584e;font-weight:700;font-size:13.5px;cursor:pointer;text-decoration:underline\">Entrar como representante</button></div>\n      </div>\n      <div id=\"repView\" style=\"display:none\">\n        <div style=\"font-weight:700;font-size:17px;color:#2c2721;margin-bottom:2px\">Área do Representante</div>\n        <div style=\"font-size:12.5px;color:#8a8073;margin-bottom:12px\">Entre com o seu e-mail e senha.</div>\n        <input id=\"repEmail\" type=\"email\" autocomplete=\"username\" placeholder=\"E-mail\" style=\"display:block;width:100%;box-sizing:border-box;padding:13px;border:1px solid #d6d0c4;border-radius:12px;font-size:16px\">\n        <input id=\"repSenha\" type=\"password\" autocomplete=\"current-password\" placeholder=\"Senha\" style=\"display:block;width:100%;box-sizing:border-box;padding:13px;border:1px solid #d6d0c4;border-radius:12px;font-size:16px;margin-top:8px\">\n        <div id=\"repMsg\" style=\"font-size:13px;min-height:1px;margin:8px 0;line-height:1.35\"></div>\n        <button id=\"repBtn\" style=\"width:100%;padding:14px;border:0;border-radius:12px;background:#2c3e50;color:#fff;font-size:16px;font-weight:600;cursor:pointer\">Entrar</button>\n        <button type=\"button\" id=\"repVoltar\" style=\"width:100%;margin-top:8px;background:none;border:0;color:#8a8073;font-size:13px;cursor:pointer\">← Voltar</button>\n      </div>\n      <div id=\"senhaView\" style=\"display:none\">\n        <div style=\"font-weight:700;font-size:17px;color:#2c2721;margin-bottom:2px\">Crie sua senha</div>\n        <div id=\"senhaQuem\" style=\"font-size:13px;color:#8a8073;margin-bottom:12px\"></div>\n        <input id=\"snNova\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Nova senha (mín. 4)\" style=\"display:block;width:100%;box-sizing:border-box;padding:13px;border:1px solid #d6d0c4;border-radius:12px;font-size:16px\">\n        <input id=\"snConf\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Repita a senha\" style=\"display:block;width:100%;box-sizing:border-box;padding:13px;border:1px solid #d6d0c4;border-radius:12px;font-size:16px;margin-top:8px\">\n        <div id=\"snMsg\" style=\"font-size:13px;min-height:1px;margin:8px 0;line-height:1.35\"></div>\n        <button id=\"snBtn\" style=\"width:100%;padding:14px;border:0;border-radius:12px;background:#ad5033;color:#fff;font-size:16px;font-weight:600;cursor:pointer\">Salvar e entrar</button>\n      </div>\n      <div id=\"cadView\" style=\"display:none\">\n        <div style=\"font-weight:700;font-size:17px;color:#2c2721;margin-bottom:2px\">Cadastrar minha loja</div>\n        <div style=\"font-size:12.5px;color:#8a8073;margin-bottom:12px\">Preencha os dados. Vamos conferir e liberar seu acesso em breve. (* obrigatório)</div>\n        <div id=\"cadMsg\" style=\"font-size:13px;min-height:1px;margin-bottom:8px;line-height:1.35\"></div>\n        <div style=\"display:grid;gap:8px;max-height:46vh;overflow:auto;padding:2px\">\n          <input id=\"cNome\" class=\"cad-inp\" placeholder=\"Razão social *\" autocomplete=\"organization\">\n          <input id=\"cFant\" class=\"cad-inp\" placeholder=\"Nome fantasia\">\n          <input id=\"cCnpj\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"CNPJ *\">\n          <input id=\"cIe\" class=\"cad-inp\" placeholder=\"Inscrição estadual (se tiver)\">\n          <input id=\"cEnd\" class=\"cad-inp\" placeholder=\"Endereço (rua)\">\n          <div style=\"display:flex;gap:8px\"><input id=\"cNum\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"Nº\" style=\"flex:0 0 84px\"><input id=\"cBai\" class=\"cad-inp\" placeholder=\"Bairro\" style=\"flex:1\"></div>\n          <div style=\"display:flex;gap:8px\"><input id=\"cCep\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"CEP\" style=\"flex:1\"><select id=\"cUf\" class=\"cad-inp\" style=\"flex:0 0 86px\"><option value=\"\">UF *</option><option>AC</option><option>AL</option><option>AP</option><option>AM</option><option>BA</option><option>CE</option><option>DF</option><option>ES</option><option>GO</option><option>MA</option><option>MT</option><option>MS</option><option>MG</option><option>PA</option><option>PB</option><option>PR</option><option>PE</option><option>PI</option><option>RJ</option><option>RN</option><option>RS</option><option>RO</option><option>RR</option><option>SC</option><option>SP</option><option>SE</option><option>TO</option></select></div>\n          <input id=\"cCid\" class=\"cad-inp\" placeholder=\"Cidade *\">\n          <input id=\"cEmail\" class=\"cad-inp\" type=\"email\" placeholder=\"E-mail\">\n          <input id=\"cTel\" class=\"cad-inp\" inputmode=\"numeric\" placeholder=\"WhatsApp / telefone\">\n          <input id=\"cSenha\" class=\"cad-inp\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Crie uma senha * (mín. 4)\">\n          <input id=\"cSenha2\" class=\"cad-inp\" type=\"password\" autocomplete=\"new-password\" placeholder=\"Repita a senha *\">\n        </div>\n        <button id=\"cadBtn\" style=\"width:100%;margin-top:12px;padding:14px;border:0;border-radius:12px;background:#ad5033;color:#fff;font-size:16px;font-weight:600;cursor:pointer\">Enviar cadastro</button>\n        <button type=\"button\" id=\"voltarEnt\" style=\"width:100%;margin-top:8px;background:none;border:0;color:#8a8073;font-size:13px;cursor:pointer\">← Voltar para o login</button>\n      </div>\n    </div>\n  </div>\n</div>\n\n<script>\n(function(){\n  \"use strict\";\n  var D = (window.__DADOS__ && typeof window.__DADOS__===\"object\") ? window.__DADOS__ : {produtos:[],banco_cores:[],banco_tamanhos:[],estoque:{itens:{}}};\n  var PRODUTOS = Array.isArray(D.produtos)?D.produtos:[];\n  var CORES = {}; (D.banco_cores||[]).forEach(function(c){CORES[c.id]=c;});\n  var TAM = {}; (D.banco_tamanhos||[]).forEach(function(t){TAM[t.id]=t;});\n  var EST = (D.estoque&&D.estoque.itens)?D.estoque.itens:{};\n  var regiao = \"sul\";\n  var LIBERADO = false;   // pode ver preços e comprar? (cliente aprovado / já é nosso)\n  var filtroTxt = \"\";\n  var sel = { prod:null, corId:null, qtd:{} }; // qtd[\"corId|cod|idtam\"] = n\n  var CART = carregarCart();\n\n  var SECOES = [\n    {key:\"pe\",     titulo:\"Pronta Entrega\", sub:\"Disponível para envio imediato\", test:function(p){return p.pronta_entrega===true;}},\n    {key:\"polisoft\",titulo:\"Linha Polisoft\", sub:\"\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&p.linha===\"polisoft\";}},\n    {key:\"soft\",   titulo:\"Linha Soft\",     sub:\"\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&p.linha===\"soft\";}},\n    {key:\"natal\",  titulo:\"Natal\",          sub:\"Coleção de Natal\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&p.linha===\"natal\";}},\n    {key:\"el\",     titulo:\"Edição Limitada\",sub:\"Peças exclusivas, em quantidade reduzida\", promo:true, test:function(p){return p._edicao_limitada===true;}},\n    {key:\"outros\", titulo:\"Outros\",         sub:\"\", test:function(p){return !p.pronta_entrega&&!p._edicao_limitada&&[\"polisoft\",\"soft\",\"natal\"].indexOf(p.linha)<0;}}\n  ];\n\n  function brl(v){ v=Number(v)||0; return \"R$ \"+v.toFixed(2).replace(\".\",\",\"); }\n  // Preço só aparece pra cliente LIBERADO. Em análise, mostra um cadeado no lugar.\n  function precoVis(v){ return LIBERADO ? brl(v) : '<span style=\"color:#b08968\">🔒</span>'; }\n  function precoLinha(l){ return Number(regiao===\"norte\"? l.norte : l.sul)||0; }\n  function menorPreco(p){ var m=Infinity; (p.grupos||[]).forEach(function(g){(g.linhas||[]).forEach(function(l){var v=precoLinha(l); if(v>0&&v<m)m=v;});}); return m===Infinity?0:m; }\n  function estoqueProduto(p){ var tot=Number(p.estoque_geral)||0; return tot; }\n  function inicial(nome){ return (String(nome||\"?\").trim()[0]||\"?\").toUpperCase(); }\n  function esc(s){ return String(s==null?\"\":s).replace(/&/g,\"&amp;\").replace(/</g,\"&lt;\").replace(/>/g,\"&gt;\").replace(/\"/g,\"&quot;\"); }\n  function findProd(id){ return PRODUTOS.filter(function(x){return String(x.id)===String(id);})[0]; }\n  function medidaDe(idt){ var t=TAM[idt]; return (t&&(t.medida||t.nome))||idt||\"-\"; }\n\n  // ---------- GRID ----------\n  function badgeHTML(p){ var est=estoqueProduto(p); return est>0?'<span class=\"badge\"><span class=\"dot\"></span>Em estoque</span>':'<span class=\"badge off\"><span class=\"dot\"></span>Sob encomenda</span>'; }\n  function cardProd(p){\n    var mp=menorPreco(p);\n    return '<article class=\"prod\" data-id=\"'+esc(p.id)+'\">'+\n      '<div class=\"foto\">'+ (p.foto? '<div class=\"ph\">'+inicial(p.nome)+'</div><img loading=\"lazy\" src=\"'+esc(p.foto)+'\" onload=\"this.style.opacity=1\" onerror=\"this.remove()\" style=\"opacity:0;transition:opacity .3s\">' : '<div class=\"ph\">'+inicial(p.nome)+'</div>') +\n        badgeHTML(p) +\n      '</div><div class=\"info\"><div class=\"nome\">'+esc(p.nome)+'</div>'+\n      (LIBERADO ? (mp? '<div class=\"preco\">a partir de <b>'+brl(mp)+'</b></div>' : '<div class=\"preco\">—</div>') : '<div class=\"preco\" style=\"color:#b08968\">🔒 preços após liberação</div>')+\n      '</div></article>';\n  }\n  // Ícones SVG (traço fino, estilo Lucide) por categoria — minimalistas e elegantes.\n  var CAT_SVG={\n    pe:'<path d=\"M21 8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16Z\"/><path d=\"m3.3 7 8.7 5 8.7-5\"/><path d=\"M12 22V12\"/>',\n    polisoft:'<path d=\"M12.83 2.18a2 2 0 0 0-1.66 0L2.6 6.08a1 1 0 0 0 0 1.83l8.58 3.91a2 2 0 0 0 1.66 0l8.58-3.9a1 1 0 0 0 0-1.83Z\"/><path d=\"m22 17.65-9.17 4.16a2 2 0 0 1-1.66 0L2 17.65\"/><path d=\"m22 12.65-9.17 4.16a2 2 0 0 1-1.66 0L2 12.65\"/>',\n    soft:'<path d=\"M20.24 12.24a6 6 0 0 0-8.49-8.49L5 10.5V19h8.5z\"/><line x1=\"16\" x2=\"2\" y1=\"8\" y2=\"22\"/><line x1=\"17.5\" x2=\"9\" y1=\"15\" y2=\"15\"/>',\n    natal:'<path d=\"m17 14 3 3.3a1 1 0 0 1-.7 1.7H4.7a1 1 0 0 1-.7-1.7L7 14h-.3a1 1 0 0 1-.7-1.7L9 9h-.2A1 1 0 0 1 8 7.3L12 3l4 4.3a1 1 0 0 1-.8 1.7H15l3 3.3a1 1 0 0 1-.7 1.7H17Z\"/><path d=\"M12 22v-3\"/>',\n    el:'<path d=\"M11.5 2.3a.56.56 0 0 1 1 0l2.35 4.76 5.26.77a.56.56 0 0 1 .3.95l-3.8 3.7.9 5.24a.56.56 0 0 1-.82.59L12 15.8l-4.7 2.3a.56.56 0 0 1-.82-.59l.9-5.24-3.8-3.7a.56.56 0 0 1 .3-.95l5.26-.77Z\"/>',\n    outros:'<rect width=\"7\" height=\"7\" x=\"3\" y=\"3\" rx=\"1.5\"/><rect width=\"7\" height=\"7\" x=\"14\" y=\"3\" rx=\"1.5\"/><rect width=\"7\" height=\"7\" x=\"14\" y=\"14\" rx=\"1.5\"/><rect width=\"7\" height=\"7\" x=\"3\" y=\"14\" rx=\"1.5\"/>'\n  };\n  function catSvg(k){ return '<svg viewBox=\"0 0 24 24\" stroke-linecap=\"round\" stroke-linejoin=\"round\" aria-hidden=\"true\">'+(CAT_SVG[k]||CAT_SVG.outros)+'</svg>'; }\n  function render(){\n    var app=document.getElementById(\"app\"), abas=document.getElementById(\"abas\"), cats=document.getElementById(\"cats\"), catsBar=document.getElementById(\"catsBar\");\n    var q=filtroTxt.toLowerCase();\n    var lista=PRODUTOS.filter(function(p){ return !q || String(p.nome||\"\").toLowerCase().indexOf(q)>=0; });\n    var html=\"\", tabs=\"\", chips=\"\", nsec=0;\n    SECOES.forEach(function(s){\n      var ps=lista.filter(s.test); if(!ps.length) return;\n      nsec++;\n      tabs+='<a data-sec=\"sec-'+s.key+'\"'+(s.promo?' class=\"promo\"':'')+'>'+esc(s.titulo)+'</a>';\n      chips+='<button type=\"button\" data-sec=\"sec-'+s.key+'\">'+catSvg(s.key)+'<span>'+esc(s.titulo)+'</span></button>';\n      html+='<section class=\"sec\" id=\"sec-'+s.key+'\"><h2 class=\"serif\">'+esc(s.titulo)+'</h2>'+(s.sub?'<div class=\"sub\">'+esc(s.sub)+'</div>':'')+'<div class=\"grade\">'+ps.map(cardProd).join(\"\")+'</div></section>';\n    });\n    abas.innerHTML=tabs; if(cats) cats.innerHTML=chips; app.innerHTML=html||'<div class=\"vazio\">Nenhum produto encontrado.</div>';\n    if(catsBar) catsBar.style.display = nsec>0 ? \"block\" : \"none\";\n    medirCatsTop(); ligarCatsAtivo();\n  }\n  // mede a altura da faixa de busca pra fixar os ícones logo abaixo dela\n  function medirCatsTop(){ try{ var b=document.querySelector(\".buscafaixa\"); if(b) document.documentElement.style.setProperty(\"--cats-top\", b.offsetHeight+\"px\"); }catch(e){} }\n  // destaca o chip da seção que está em vista (rolagem)\n  var catObs=null;\n  function ligarCatsAtivo(){\n    try{\n      if(catObs){ catObs.disconnect(); catObs=null; }\n      var cats=document.getElementById(\"cats\"); if(!cats || !(\"IntersectionObserver\" in window)) return;\n      var btns={}; cats.querySelectorAll(\"button[data-sec]\").forEach(function(b){ btns[b.getAttribute(\"data-sec\")]=b; });\n      var secs=document.querySelectorAll(\"#app section.sec\"); if(!secs.length) return;\n      catObs=new IntersectionObserver(function(entries){\n        entries.forEach(function(en){ if(en.isIntersecting){ Object.keys(btns).forEach(function(k){ btns[k].classList.toggle(\"on\", k===en.target.id); }); } });\n      },{rootMargin:\"-45% 0px -50% 0px\",threshold:0});\n      secs.forEach(function(s){ catObs.observe(s); });\n    }catch(e){}\n  }\n  window.addEventListener(\"resize\", medirCatsTop);\n  // WhatsApp flutuante (número vem do D.whatsapp; sem número, esconde o botão)\n  function ligarWhatsApp(){\n    var el=document.getElementById(\"waFloat\"); if(!el) return;\n    var wa=String(D.whatsapp||\"\").replace(/\\D/g,\"\"); if(wa && wa.length<=11) wa=\"55\"+wa;\n    if(!wa){ el.style.display=\"none\"; return; }\n    el.href=\"https://wa.me/\"+wa+\"?text=\"+encodeURIComponent(\"Olá! Vim pelo catálogo da Big Tricot 😊\");\n    el.style.display=\"flex\";\n  }\n\n  // ---------- BANNER / CARROSSEL ----------\n  // Lê D.banners (lista, só os ativos). 0 → estado padrão elegante (sem foto fictícia).\n  // 1 → mostra fixo (sem setas/bolinhas/troca). 2+ → carrossel com fade, bolinhas,\n  // setas (desktop), swipe (celular), autoplay (pausa ao interagir) e respeita movimento reduzido.\n  function bannerSlide(b,i){\n    var imgTag=\"\";\n    if(b.img||b.img_mobile){\n      imgTag='<picture>'+\n        (b.img_mobile?'<source media=\"(max-width:640px)\" srcset=\"'+esc(b.img_mobile)+'\">':'')+\n        '<img class=\"b-bg\" '+(i===0?'':'loading=\"lazy\" ')+'src=\"'+esc(b.img||b.img_mobile)+'\" alt=\"\" onerror=\"this.remove()\">'+\n      '</picture>';\n    }\n    var conteudo=imgTag+'<div class=\"b-shade\"></div><div class=\"b-in\">'+\n      (b.kicker?'<div class=\"b-kick\">'+esc(b.kicker)+'</div>':'')+\n      (b.titulo?'<div class=\"b-tit serif\">'+esc(b.titulo)+'</div>':'')+\n      (b.sub?'<div class=\"b-sub\">'+esc(b.sub)+'</div>':'')+\n      (b.botao_texto?'<a class=\"b-btn\" href=\"'+esc(b.botao_link||'#')+'\"'+(b.botao_link?' target=\"_blank\" rel=\"noopener\"':'')+'>'+esc(b.botao_texto)+' ›</a>':'')+\n    '</div>';\n    // Banner inteiro clicável: produto do catálogo tem PRIORIDADE (abre a janela do produto);\n    // senão, link externo. Nunca cria botão por cima da imagem.\n    var pid=(b.produto_id!=null? String(b.produto_id):\"\").replace(/[^\\w\\-.]/g,\"\");\n    if(pid){\n      conteudo='<div class=\"b-link\" style=\"cursor:pointer\" onclick=\"__abrirProd(\\''+pid+'\\')\">'+conteudo+'</div>';\n    } else if(b.botao_link && !b.botao_texto){\n      conteudo='<a class=\"b-link\" href=\"'+esc(b.botao_link)+'\" target=\"_blank\" rel=\"noopener\">'+conteudo+'</a>';\n    }\n    return '<div class=\"b-slide'+(i===0?' on':'')+'\">'+conteudo+'</div>';\n  }\n  function renderBanner(){\n    var el=document.getElementById(\"banner\"); if(!el) return;\n    var bs = Array.isArray(D.banners)? D.banners.filter(function(b){return b && b.ativo!==false;}) : [];\n    if(!bs.length){\n      el.innerHTML='<div class=\"b-slide on\"><div class=\"b-shade\"></div><div class=\"b-in\">'+\n        '<div class=\"b-kick\">Big Tricot · Home Decor</div>'+\n        '<div class=\"b-tit serif\">Tricô que transforma ambientes</div>'+\n        '<div class=\"b-sub\">Qualidade · Design · Pronta entrega</div>'+\n      '</div></div>';\n      return;\n    }\n    var slides=bs.map(bannerSlide).join(\"\");\n    if(bs.length===1){ el.innerHTML=slides; return; } // 1 só: fixo, sem controles\n    var dots='<div class=\"b-dots\">'+bs.map(function(_,i){return '<button class=\"b-dot'+(i===0?' on':'')+'\" data-i=\"'+i+'\" aria-label=\"Ir para banner '+(i+1)+'\"></button>';}).join(\"\")+'</div>';\n    var setas='<button class=\"b-arrow b-prev\" aria-label=\"Anterior\">‹</button><button class=\"b-arrow b-next\" aria-label=\"Próximo\">›</button>';\n    el.innerHTML=slides+setas+dots;\n\n    var reduz = !!(window.matchMedia && window.matchMedia(\"(prefers-reduced-motion: reduce)\").matches);\n    var intervalo = Math.max(2000, (Number(D.banner_intervalo)||5)*1000);\n    var slidesEl=el.querySelectorAll(\".b-slide\"), dotsEl=el.querySelectorAll(\".b-dot\");\n    var atual=0, timer=null;\n    function mostrar(i){ atual=(i+bs.length)%bs.length; for(var j=0;j<slidesEl.length;j++) slidesEl[j].classList.toggle(\"on\",j===atual); for(var k=0;k<dotsEl.length;k++) dotsEl[k].classList.toggle(\"on\",k===atual); }\n    function proximo(){ mostrar(atual+1); }\n    function parar(){ if(timer){ clearInterval(timer); timer=null; } }\n    function iniciar(){ parar(); if(!reduz) timer=setInterval(proximo,intervalo); }\n    function reagendar(){ parar(); if(!reduz) setTimeout(iniciar, Math.max(intervalo, 6000)); }\n    var prev=el.querySelector(\".b-prev\"), next=el.querySelector(\".b-next\");\n    if(prev) prev.onclick=function(){ mostrar(atual-1); reagendar(); };\n    if(next) next.onclick=function(){ proximo(); reagendar(); };\n    for(var d=0; d<dotsEl.length; d++){ (function(btn){ btn.onclick=function(){ mostrar(Number(btn.getAttribute(\"data-i\"))||0); reagendar(); }; })(dotsEl[d]); }\n    // swipe no celular\n    var x0=null;\n    el.addEventListener(\"touchstart\", function(e){ x0=e.touches[0].clientX; parar(); }, {passive:true});\n    el.addEventListener(\"touchend\", function(e){ if(x0==null) return; var dx=e.changedTouches[0].clientX-x0; if(Math.abs(dx)>40){ if(dx<0) proximo(); else mostrar(atual-1); } x0=null; reagendar(); }, {passive:true});\n    // pausa ao interagir com o mouse (desktop)\n    el.addEventListener(\"mouseenter\", parar);\n    el.addEventListener(\"mouseleave\", iniciar);\n    iniciar();\n  }\n\n  // ---------- MODAL PRODUTO ----------\n  function corAtual(p){ if(sel.corId){ var c=(p.cores||[]).filter(function(x){return x.id_cor===sel.corId;})[0]; if(c) return c; } return (p.cores||[]).filter(function(x){return !x.oculta;})[0] || (p.cores||[])[0] || null; }\n  function qKey(cod,idt){ return sel.corId+\"|\"+cod+\"|\"+idt; }\n\n  function abrir(id){\n    var p=findProd(id); if(!p) return;\n    sel.prod=p; sel.qtd={};\n    var vis=coresVisiveis(p);\n    var c0=vis[0] || (p.cores||[]).filter(function(x){return !x.oculta;})[0] || (p.cores||[])[0];\n    sel.corId=c0?c0.id_cor:null;\n    renderDetalhe();\n    document.getElementById(\"modal\").classList.add(\"show\");\n    document.body.style.overflow=\"hidden\";\n  }\n  window.__fechar=function(){ document.getElementById(\"modal\").classList.remove(\"show\"); document.body.style.overflow=\"\"; };\n\n  function blocosHTML(p){\n    var b=p.blocos; if(!b||typeof b!==\"object\") return \"\";\n    return Object.keys(b).map(function(k){\n      var v=String(b[k]==null?\"\":b[k]).trim(); if(!v) return \"\";\n      var itens=v.split(\"\\n\").map(function(x){return x.trim();}).filter(Boolean).map(function(x){return \"<li>\"+esc(x)+\"</li>\";}).join(\"\");\n      return '<div class=\"bloco\"><h5>'+esc(k)+'</h5><ul>'+itens+'</ul></div>';\n    }).join(\"\");\n  }\n  // Cores como BOLINHAS com a textura real (a mesma foto cc.foto que já existe).\n  // Sem foto → cai na cor sólida (hex). Nome: no tooltip + destacado na área da cor.\n  function coresHTML(p){\n    // quantas peças já foram escolhidas em cada cor (pra marcar as bolinhas)\n    var porCor={};\n    Object.keys(sel.qtd).forEach(function(k){ var q=Number(sel.qtd[k])||0; if(q<=0) return; var corId=k.slice(0,k.indexOf(\"|\")); porCor[corId]=(porCor[corId]||0)+q; });\n    return coresVisiveis(p).map(function(c){\n      var cc=CORES[c.id_cor]||{}; var on=String(c.id_cor)===String(sel.corId)?\" on\":\"\";\n      var fundo=cc.foto? \"background-image:url('\"+esc(cc.foto)+\"')\" : 'background-color:'+esc(cc.hex||\"#ddd\");\n      var n=porCor[c.id_cor]||0; var badge=n>0?'<span class=\"sw-n\">'+n+'</span>':'';\n      return '<button type=\"button\" class=\"sw-dot'+on+(n>0?' has':'')+'\" data-cor=\"'+esc(c.id_cor)+'\" title=\"'+esc(cc.nome||\"\")+'\" aria-label=\"'+esc(cc.nome||\"\")+'\" style=\"'+fundo+'\">'+badge+'</button>';\n    }).join(\"\");\n  }\n  function corFotoHTML(p){\n    var cc=CORES[sel.corId]||{}; if(!cc.nome) return \"\";\n    var img=cc.foto? '<img class=\"cf-img\" src=\"'+esc(cc.foto)+'\" data-nome=\"'+esc(cc.nome||\"\")+'\" onclick=\"__zoomCor(this.src,this.getAttribute(\\'data-nome\\'))\" onerror=\"this.style.display=\\'none\\'\">' : '<div class=\"cf-img ph\"></div>';\n    return '<div class=\"corfoto\">'+img+'<div class=\"cf-d\"><div class=\"cf-nm\">'+esc(cc.nome)+'</div>'+(cc.foto?'<div class=\"cf-amp\">🔍 clique para ampliar</div>':'')+'</div></div>';\n  }\n  // Lightbox da foto do tecido da cor (abre a imagem grande pro cliente ver o detalhe).\n  window.__zoomCor=function(src,nome){\n    if(!src) return;\n    var ov=document.createElement(\"div\"); ov.className=\"lightbox\";\n    ov.innerHTML='<img src=\"'+src+'\" alt=\"\">'+(nome?'<div class=\"cap\">'+esc(nome)+'</div>':'')+'<button class=\"lb-x\" aria-label=\"fechar\">✕</button>';\n    document.body.appendChild(ov);\n    ov.addEventListener(\"click\",function(){ try{document.body.removeChild(ov);}catch(e){} });\n  };\n  // saldo da variação (produto+tamanho+cor selecionada), se o estoque por variação existir.\n  function estSaldo(cod,idt){\n    var med=medidaDe(idt); var m=EST[cod]&&EST[cod][med]; if(!m) return null;\n    var v=m[sel.corId]; return (v==null)?null:(Number(v)||0);\n  }\n  // saldo de uma COR específica (pra ocultar opção/cor sem estoque)\n  function estSaldoCor(cod,idt,corId){ var med=medidaDe(idt); var m=EST[cod]&&EST[cod][med]; if(!m) return null; var v=m[corId]; return (v==null)?null:(Number(v)||0); }\n  // só filtra se for pronta entrega/kit E houver dados de estoque (senão não esconde nada)\n  function filtraEstoque(p){ if(!(p.pronta_entrega||p._kit)) return false; var has=false; (p.grupos||[]).forEach(function(g){(g.linhas||[]).forEach(function(l){ if(EST[l.cod]) has=true; });}); return has; }\n  // a cor tem estoque em ALGUM tamanho?\n  function corComEstoque(p,corId){ var ok=false; (p.grupos||[]).forEach(function(g){(g.linhas||[]).forEach(function(l){ var s=estSaldoCor(l.cod,l.id_tamanho,corId); if(s!=null&&s>0) ok=true; });}); return ok; }\n  // cores a mostrar: oculta as sem estoque (pronta entrega/kit); nunca deixa a lista vazia\n  function coresVisiveis(p){ var cs=(p.cores||[]).filter(function(c){return !c.oculta;}); if(!filtraEstoque(p)) return cs; var cE=cs.filter(function(c){return corComEstoque(p,c.id_cor);}); return cE.length?cE:cs; }\n  // texto de estoque por linha, no estilo do catálogo: \"7 em estoque\" / \"últimas 2 unidades\".\n  function estTxtLinha(cod,idt){\n    var s=estSaldo(cod,idt); if(s==null) return \"\";\n    // Pronta entrega / kit: estoque 0 = ESGOTADO (não é feito sob encomenda).\n    var pe = sel.prod && (sel.prod.pronta_entrega || sel.prod._kit);\n    if(s<=0) return '<div class=\"estx off\">'+(pe?'estoque esgotado':'sob encomenda')+'</div>';\n    if(s<=3) return '<div class=\"estx low\">'+(s===1?'última unidade':'últimas '+s+' unidades')+'</div>';\n    return '<div class=\"estx\">'+s+' em estoque</div>';\n  }\n  function tamanhosHTML(p){\n    var cc=CORES[sel.corId]||{}; var filtra=filtraEstoque(p);\n    var grupos=(p.grupos||[]).map(function(g){\n      var rows=(g.linhas||[]).map(function(l){\n        // pronta entrega/kit: oculta a opção SEM estoque na cor selecionada\n        if(filtra){ var s=estSaldo(l.cod,l.id_tamanho); if(s!=null&&s<=0) return \"\"; }\n        var k=qKey(l.cod,l.id_tamanho); var q=sel.qtd[k]||0;\n        return '<div class=\"tamrow\"><div class=\"medbox\"><div class=\"med\">'+esc(medidaDe(l.id_tamanho).replace(/(\\d)\\s*[×xX]\\s*(\\d)/g,\"$1 × $2\"))+'</div>'+estTxtLinha(l.cod,l.id_tamanho)+'</div>'+\n          '<div class=\"pr\">'+precoVis(precoLinha(l))+'</div>'+\n          (REP_SOVER ? '' : (LIBERADO ? '<div class=\"stepper\" data-k=\"'+esc(k)+'\"><button data-d=\"-1\">−</button><input type=\"number\" min=\"0\" value=\"'+q+'\"><button data-d=\"1\">+</button></div>' : '<div class=\"pr\" style=\"opacity:.6;font-size:11px\">—</div>'))+'</div>';\n      }).join(\"\");\n      if(!rows) return \"\";                    // seção sem nenhuma opção visível → some\n      return '<div class=\"grp\"><div class=\"t\">'+esc(g.titulo||\"Itens\")+'</div>'+rows+'</div>';\n    }).join(\"\");\n    if(!grupos) grupos='<div class=\"estx off\" style=\"padding:10px 0\">Sem opções em estoque nesta cor.</div>';\n    return '<div class=\"lbl\">'+(REP_SOVER?'Tamanhos e preços':'Escolha os tamanhos')+' — <b>'+esc(cc.nome||\"\")+'</b></div>'+grupos;\n  }\n  function prazoHTML(p){\n    var est=estoqueProduto(p);\n    return '<div class=\"prazo\">'+(est>0? '📦 Em estoque — envio rápido.' : '🧶 Produção sob encomenda.')+'</div>';\n  }\n  // Mapa de todas as linhas do produto por \"cod|idtam\" (pra achar preço/medida a\n  // partir da chave de quantidade, que é \"corId|cod|idtam\").\n  function linhasDoProd(p){\n    var m={};\n    (p.grupos||[]).forEach(function(g){ (g.linhas||[]).forEach(function(l){ m[l.cod+\"|\"+l.id_tamanho]={l:l,g:g}; }); });\n    return m;\n  }\n  // Resumo do pedido (peças + valor) — soma TODAS as cores selecionadas (não só a\n  // cor que está aberta), pra a cliente ver o total real antes de adicionar.\n  function resumoHTML(p){\n    var pecas=0, total=0, LIN=linhasDoProd(p);\n    // o que está selecionando AGORA (ainda não adicionado)\n    Object.keys(sel.qtd).forEach(function(k){\n      var q=Number(sel.qtd[k])||0; if(q<=0) return;\n      var i=k.indexOf(\"|\"); var lk=k.slice(i+1);\n      var ref=LIN[lk]; if(!ref) return;\n      pecas+=q; total+=q*precoLinha(ref.l);\n    });\n    // o que JÁ está no carrinho DESTE modelo (não zera ao adicionar — só some ao fechar a compra)\n    var cp=0, ct=0;\n    (CART||[]).forEach(function(it){ if(it.pid===p.id){ cp+=Number(it.qtd)||0; ct+=(Number(it.qtd)||0)*(Number(it.preco)||0); } });\n    var tp=pecas+cp, tt=total+ct;\n    if(!LIBERADO) return '<span class=\"rz-q\" style=\"color:#b08968\">🔒 Preços e pedidos liberam após a aprovação do seu cadastro</span>';\n    var nota = cp>0 ? '<span class=\"rz-c\">'+cp+' no carrinho</span>' : '';\n    return '<span class=\"rz-q\">'+tp+' '+(tp===1?'peça':'peças')+'</span>'+nota+'<b class=\"rz-v\">'+brl(tt)+'</b>';\n  }\n  function atualizarResumo(){ var el=document.getElementById(\"resumo\"); if(el) el.innerHTML=resumoHTML(sel.prod); }\n  function renderDetalhe(){\n    var p=sel.prod;\n    var foto = p.foto? '<div class=\"ph\">'+inicial(p.nome)+'</div><img src=\"'+esc(p.foto)+'\" onerror=\"this.remove()\">' : '<div class=\"ph\">'+inicial(p.nome)+'</div>';\n    var video = p.video? '<video class=\"vid\" controls preload=\"metadata\" src=\"'+esc(p.video)+'\"></video>' : '';\n    var linhaLb = p.pronta_entrega?\"Pronta Entrega\":(p._edicao_limitada?\"Edição Limitada\":(\"Linha \"+(p.linha||\"\").replace(/^\\w/,function(c){return c.toUpperCase();})));\n    var ncores=coresVisiveis(p).length;\n    document.getElementById(\"sheet\").innerHTML =\n      '<div class=\"topo\"><span class=\"lb\">'+esc(linhaLb)+'</span><button class=\"fechar\" onclick=\"__fechar()\">✕</button></div>'+\n      '<div class=\"det\">'+\n        '<div class=\"lado-foto\">'+foto+'</div>'+\n        '<div class=\"lado-info\">'+\n          '<div class=\"linhalb\">'+esc(linhaLb)+'</div>'+\n          '<h3 class=\"nome serif\">'+esc(p.nome)+'</h3>'+\n          video+\n          (p.composicao?'<div class=\"comp\">'+esc(p.composicao)+'</div>':'')+\n          blocosHTML(p)+\n          prazoHTML(p)+\n          '<div class=\"montar\"><h4>'+(REP_SOVER?'Preços e estoque':'Montar pedido')+'</h4>'+\n            '<div class=\"cor-sticky\">'+\n              '<div class=\"lbl\">'+(REP_SOVER?'Cores':'Escolha a cor')+(ncores>1?' <span class=\"cnt\">· '+ncores+' cores disponíveis</span>':'')+'</div><div class=\"cores\" id=\"cores\">'+coresHTML(p)+'</div>'+\n              '<div id=\"corfoto\">'+corFotoHTML(p)+'</div>'+\n            '</div>'+\n            '<div id=\"tamanhos\">'+tamanhosHTML(p)+'</div>'+\n            (REP_SOVER ? '<div style=\"text-align:center;padding:11px;border:1px dashed #cdd6e2;border-radius:12px;color:#8a8073;font-size:13px;background:#f7f5f0;margin-top:4px\">👁️ Só visualização. Para montar o pedido, volte e escolha um cliente.</div>' :\n              ('<div class=\"resumo\" id=\"resumo\">'+resumoHTML(p)+'</div>'+\n               (LIBERADO ? '<button class=\"addcart\" id=\"addcart\">Adicionar ao carrinho</button>' : '<div style=\"text-align:center;padding:12px;border:1px dashed #d6c6b0;border-radius:12px;color:#8a6d4f;font-size:13.5px;background:#fbf6ef\">🔒 Seu cadastro está em análise. Assim que a Big Tricot aprovar, os preços e o pedido liberam aqui.</div>')))+\n          '</div>'+\n        '</div>'+\n      '</div>';\n    ligarDetalhe();\n  }\n  function atualizarCorArea(){\n    document.getElementById(\"cores\").innerHTML=coresHTML(sel.prod);\n    document.getElementById(\"corfoto\").innerHTML=corFotoHTML(sel.prod);\n    document.getElementById(\"tamanhos\").innerHTML=tamanhosHTML(sel.prod);\n    ligarTamanhos();\n    atualizarResumo();\n  }\n  function ligarDetalhe(){\n    document.getElementById(\"cores\").onclick=function(e){ var c=e.target.closest(\".sw-dot\"); if(!c)return; sel.corId=c.getAttribute(\"data-cor\"); atualizarCorArea(); };\n    var ac=document.getElementById(\"addcart\"); if(ac) ac.onclick=adicionarAoCarrinho;\n    ligarTamanhos();\n  }\n  function ligarTamanhos(){\n    var box=document.getElementById(\"tamanhos\");\n    box.querySelectorAll(\".stepper\").forEach(function(st){\n      var k=st.getAttribute(\"data-k\"); var inp=st.querySelector(\"input\");\n      st.querySelectorAll(\"button\").forEach(function(b){ b.onclick=function(){ var d=Number(b.getAttribute(\"data-d\")); var v=Math.max(0,(Number(inp.value)||0)+d); inp.value=v; sel.qtd[k]=v; atualizarResumo(); }; });\n      inp.oninput=function(){ sel.qtd[k]=Math.max(0,Number(inp.value)||0); atualizarResumo(); };\n    });\n  }\n  function adicionarAoCarrinho(){\n    if(REP_SOVER){ alert(\"Você está só vendo o catálogo. Para montar um pedido, toque em ← Voltar e escolha um cliente. 👈\"); return; }\n    if(!LIBERADO){ alert(\"Seu cadastro ainda está em análise. Assim que a Big Tricot aprovar, você poderá montar o pedido. 💛\"); return; }\n    var p=sel.prod, add=0, LIN=linhasDoProd(p);\n    // Percorre TODAS as cores selecionadas (a chave é \"corId|cod|idtam\") — não só a\n    // cor que está aberta —, pra todas as cores escolhidas entrarem no carrinho.\n    Object.keys(sel.qtd).forEach(function(k){\n      var q=Number(sel.qtd[k])||0; if(q<=0) return;\n      var i=k.indexOf(\"|\"); var corId=k.slice(0,i), lk=k.slice(i+1);\n      var ref=LIN[lk]; if(!ref) return;\n      var l=ref.l, g=ref.g, cc=CORES[corId]||{}, preco=precoLinha(l);\n      var achou=CART.filter(function(it){return it.cod===l.cod&&it.id_tamanho===l.id_tamanho&&String(it.corId)===String(corId)&&it.regiao===regiao;})[0];\n      if(achou){ achou.qtd+=q; } else {\n        CART.push({pid:p.id, nome:p.nome, grupo:g.titulo||\"\", cod:l.cod, id_tamanho:l.id_tamanho, medida:medidaDe(l.id_tamanho), corId:corId, corNome:cc.nome||\"\", preco:preco, regiao:regiao, qtd:q});\n      }\n      add+=q;\n    });\n    if(!add){ alert(\"Escolha a quantidade de pelo menos um tamanho.\"); return; }\n    sel.qtd={}; // zera a seleção de todas as cores\n    salvarCart(); atualizarCartN();\n    // feedback: zera os inputs e pergunta se continua no mesmo modelo ou escolhe outro\n    atualizarCorArea();\n    perguntarContinuar(add);\n  }\n  // Popup após adicionar: continuar neste modelo (fica no produto) ou escolher outro (volta ao catálogo).\n  function perguntarContinuar(add){\n    var ov=document.createElement(\"div\"); ov.className=\"popconf\";\n    ov.innerHTML=\n      '<div class=\"popconf-box\" role=\"dialog\" aria-modal=\"true\">'+\n        '<div class=\"popconf-ic\">🛒</div>'+\n        '<div class=\"popconf-tit\">'+add+' peça'+(add>1?'s':'')+' no carrinho!</div>'+\n        '<div class=\"popconf-sub\">Quer continuar neste modelo ou escolher outro?</div>'+\n        '<div class=\"popconf-acts\">'+\n          '<button class=\"popconf-b1\">Continuar neste modelo</button>'+\n          '<button class=\"popconf-b2\">Escolher outro modelo</button>'+\n        '</div>'+\n        '<button class=\"popconf-cart\">🛒 Ver meu carrinho</button>'+\n      '</div>';\n    document.body.appendChild(ov);\n    function fechar(){ try{ document.body.removeChild(ov); }catch(e){} }\n    ov.addEventListener(\"click\",function(e){ if(e.target===ov) fechar(); });\n    ov.querySelector(\".popconf-b1\").onclick=function(){ fechar(); };                         // segue no mesmo produto\n    ov.querySelector(\".popconf-b2\").onclick=function(){ fechar(); window.__fechar(); };        // fecha o produto → volta ao catálogo\n    ov.querySelector(\".popconf-cart\").onclick=function(){ fechar(); window.__fechar(); abrirCarrinho(); };\n  }\n\n  // ---------- CARRINHO ----------\n  function cnpjSalvo(){ try{ return localStorage.getItem(\"bt_cnpj\")||\"\"; }catch(e){ return \"\"; } }\n  function hashStr(s){ var h=5381,i=s.length; while(i){ h=(h*33)^s.charCodeAt(--i); } return (h>>>0).toString(36); }\n  function carregarCart(){ try{ return JSON.parse(localStorage.getItem(\"bt_carrinho\")||\"[]\")||[]; }catch(e){ return []; } }\n  function salvarCart(){ try{ localStorage.setItem(\"bt_carrinho\", JSON.stringify(CART)); }catch(e){} }\n  function cartQtd(){ return CART.reduce(function(s,i){return s+(Number(i.qtd)||0);},0); }\n  function cartTotal(){ return CART.reduce(function(s,i){return s+(Number(i.qtd)||0)*(Number(i.preco)||0);},0); }\n  function atualizarCartN(){ document.getElementById(\"cartN\").textContent=cartQtd(); }\n  function abrirCarrinho(){ renderCarrinho(); document.getElementById(\"cart\").classList.add(\"show\"); document.body.style.overflow=\"hidden\"; }\n  window.__fecharCart=function(){ document.getElementById(\"cart\").classList.remove(\"show\"); if(!document.getElementById(\"modal\").classList.contains(\"show\")) document.body.style.overflow=\"\"; };\n\n  // ÁREA DO CLIENTE — \"Meus pedidos\"\n  window.__fecharMeus=function(){ document.getElementById(\"meus\").classList.remove(\"show\"); document.body.style.overflow=\"\"; };\n  function cabMeus(){ return '<div class=\"ctopo\"><h3 class=\"serif\">👤 Meus pedidos</h3><button class=\"fechar\" onclick=\"__fecharMeus()\">✕</button></div>'; }\n  function abrirMeus(){\n    var pane=document.getElementById(\"meusPane\");\n    document.getElementById(\"meus\").classList.add(\"show\"); document.body.style.overflow=\"hidden\";\n    var cnpj=cnpjSalvo();\n    if(!cnpj){ pane.innerHTML=cabMeus()+'<div class=\"itens\"><div class=\"cvazio\">Entre com o CNPJ da sua loja para ver seus pedidos.</div></div>'; abrirEntrada(); return; }\n    pane.innerHTML=cabMeus()+'<div class=\"itens\"><div class=\"cvazio\">Carregando seus pedidos…</div></div>';\n    fetch(\"/api/loja/meus-pedidos?cnpj=\"+encodeURIComponent(cnpj)).then(function(r){return r.json();}).then(function(d){ renderMeus(d.pedidos||[]); })\n      .catch(function(){ pane.innerHTML=cabMeus()+'<div class=\"itens\"><div class=\"cvazio\">Não consegui carregar agora. Tente de novo.</div></div>'; });\n  }\n  function fmtDataHora(s){\n    s=String(s||\"\").replace(\"T\",\" \");\n    var m=s.match(/(\\d{4})-(\\d{2})-(\\d{2})[ ]?(\\d{2}):(\\d{2})/);\n    if(!m) return s.slice(0,16);\n    return m[3]+\"/\"+m[2]+\"/\"+m[1]+\" às \"+m[4]+\":\"+m[5];\n  }\n  function chevSvg(){ return '<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m6 9 6 6 6-6\"/></svg>'; }\n  // Abre/fecha um pedido; mantém só UM aberto por vez.\n  window.__mpToggle=function(ix){\n    var cur=document.getElementById(\"mpc-\"+ix); if(!cur) return;\n    var abrir=!cur.classList.contains(\"open\");\n    document.querySelectorAll(\"#meusPane .mp-card\").forEach(function(c){ c.classList.remove(\"open\"); });\n    if(abrir) cur.classList.add(\"open\");\n  };\n  function renderMeus(peds){\n    var pane=document.getElementById(\"meusPane\");\n    if(!peds.length){ pane.innerHTML=cabMeus()+'<div class=\"itens\"><div class=\"cvazio\">Você ainda não tem pedidos por aqui. 🧶<br>Monte seu pedido no catálogo.</div></div>'; return; }\n    var html=peds.map(function(p,ix){\n      var data=fmtDataHora(p.data);\n      var pecas=Number(p.pecas)||0;\n      var itens=(p.itens||[]).map(function(it){\n        return '<div class=\"mp-it\"><span class=\"mp-nm\">'+esc(it.produto||it.ref||\"—\")+'</span><span class=\"mp-d\">'+esc(it.cor||\"\")+(it.tamanho?' · '+esc(it.tamanho):'')+'</span><span class=\"mp-q\">'+(Number(it.qtd)||0)+'×</span></div>';\n      }).join(\"\");\n      var numTxt = p.numero ? ('Pedido nº '+p.numero) : 'Pedido';\n      return '<div class=\"mp-card\" id=\"mpc-'+ix+'\">'+\n        '<button class=\"mp-head\" onclick=\"__mpToggle('+ix+')\">'+\n          '<div class=\"mp-l1\">'+\n            '<span class=\"mp-badge '+esc(p.status||'recebido')+'\"><span class=\"dot\"></span>'+esc(p.status_label||p.situacao||\"\")+'</span>'+\n            '<span class=\"mp-num\">'+esc(numTxt)+'</span>'+\n            '<span class=\"mp-chev\">'+chevSvg()+'</span>'+\n          '</div>'+\n          '<div class=\"mp-cli\">'+esc(p.cliente||\"Cliente não identificado\")+'</div>'+\n          '<div class=\"mp-l2\"><span class=\"mp-dt\">'+esc(data)+'</span><span class=\"mp-sep\">·</span><span>'+pecas+' '+(pecas===1?'peça':'peças')+'</span><span class=\"mp-tot\">'+brl(p.total)+'</span></div>'+\n        '</button>'+\n        '<div class=\"mp-body\">'+(itens||'<div class=\"mp-it\"><span class=\"mp-d\">Sem itens.</span></div>')+'</div>'+\n      '</div>';\n    }).join(\"\");\n    pane.innerHTML=cabMeus()+'<div class=\"itens\">'+html+'</div>';\n  }\n  function renderCarrinho(){\n    var linhas = CART.map(function(it,ix){\n      var desc=[it.grupo, it.medida, it.corNome].filter(Boolean).join(\" · \");\n      var sub=(Number(it.qtd)||0)*(Number(it.preco)||0);\n      return '<tr>'+\n        '<td class=\"c-prod\" title=\"'+esc(it.nome)+'\">'+esc(it.nome)+'</td>'+\n        '<td class=\"c-desc\" title=\"'+esc(desc)+'\">'+esc(desc)+'</td>'+\n        '<td class=\"c-qtd\"><div class=\"stepper mini\" data-ix=\"'+ix+'\"><button data-d=\"-1\">−</button><input type=\"number\" min=\"1\" value=\"'+(Number(it.qtd)||0)+'\"><button data-d=\"1\">+</button></div></td>'+\n        '<td class=\"c-val\">'+brl(sub)+'</td>'+\n        '<td class=\"c-rm\"><button data-rm=\"'+ix+'\" title=\"Excluir\" aria-label=\"Excluir\">🗑</button></td>'+\n      '</tr>';\n    }).join(\"\");\n    var itens = CART.length\n      ? '<table class=\"ctbl\"><thead><tr><th class=\"c-prod\">Produto</th><th class=\"c-desc\">Descrição</th><th class=\"c-qtd\">Qtd.</th><th class=\"c-val\">Valor</th><th class=\"c-rm\"></th></tr></thead><tbody>'+linhas+'</tbody></table>'\n      : '<div class=\"cvazio\">Seu carrinho está vazio.<br>Escolha um produto e monte seu pedido.</div>';\n    var nomeCab = REP_CLIENTE ? (REP_CLIENTE.fantasia||REP_CLIENTE.nome||\"\") : \"\";\n    var footHTML;\n    if(REP_CLIENTE){\n      // Carrinho no modo REPRESENTANTE: forma de pagamento + botões (espera / PDF / enviar à Big).\n      var opts='<option value=\"\">Forma de pagamento *</option>'+REP_PRAZOS.map(function(p){ return '<option value=\"'+esc(p.codigo)+'\"'+(String(p.codigo)===String(REP_PEDIDO_FORMA||\"\")?\" selected\":\"\")+'>'+esc(p.descricao||p.codigo)+'</option>'; }).join(\"\");\n      footHTML='<div class=\"cfoot\"><div class=\"tot\"><span>Total</span><b>'+brl(cartTotal())+'</b></div>'+\n        (CART.length?(\n          '<select id=\"repForma\" class=\"cad-inp cart-inp\" style=\"width:100%;margin:0 0 7px\">'+opts+'</select>'+\n          '<input id=\"repObs\" class=\"cad-inp cart-inp\" placeholder=\"Observação (opcional)\" value=\"'+esc(REP_PEDIDO_OBS||\"\")+'\" style=\"width:100%;margin:0 0 7px\">'+\n          '<div id=\"cmsg\" style=\"font-size:12.5px;margin:0 0 7px;min-height:1px;line-height:1.3\"></div>'+\n          '<button class=\"fin\" id=\"repPdf\" style=\"background:#2c3e50;margin-bottom:7px\">📄 Gerar PDF e enviar ao cliente</button>'+\n          '<div style=\"display:flex;gap:7px;align-items:stretch\">'+\n            '<button id=\"repEspera\" style=\"flex:1;min-height:44px;padding:8px 6px;border:1.5px solid #d6cfc2;border-radius:10px;background:#fff;color:#5f584e;font-size:12.5px;font-weight:600;cursor:pointer;line-height:1.2\">⏸️ Deixar em espera</button>'+\n            '<button id=\"repContinuar\" style=\"flex:1;min-height:44px;padding:8px 6px;border:1.5px solid #ae5033;border-radius:10px;background:#fff;color:#ae5033;font-size:12.5px;font-weight:600;cursor:pointer;line-height:1.2\">🛍️ Continuar comprando</button>'+\n            '<button id=\"repEnviarBig\" style=\"flex:1;min-height:44px;padding:8px 6px;border:0;border-radius:10px;background:#1f7a4d;color:#fff;font-size:12.5px;font-weight:600;cursor:pointer;line-height:1.2\">✅ Enviar à Big</button>'+\n          '</div>'+\n          '<div style=\"font-size:11px;color:#9aa3af;margin-top:7px;line-height:1.35\">O pedido só vai pro Syntech depois que a Big Tricot aprovar.</div>'\n        ):'')+'</div>';\n    } else {\n      footHTML='<div class=\"cfoot\"><div class=\"tot\"><span>Total</span><b>'+brl(cartTotal())+'</b></div>'+\n        (CART.length?('<label style=\"display:block;font-size:15px;color:#555;margin:2px 0 8px\">Informe o CNPJ da sua loja'+\n          '<input id=\"cnpjInp\" type=\"text\" inputmode=\"numeric\" autocomplete=\"off\" placeholder=\"00.000.000/0000-00\" value=\"'+esc(cnpjSalvo())+'\" style=\"display:block;width:100%;box-sizing:border-box;margin-top:4px;padding:12px;border:1px solid #d6d0c4;border-radius:10px;font-size:16px\"></label>'+\n          '<div id=\"cmsg\" style=\"font-size:13px;margin:0 0 8px;min-height:1px;line-height:1.35\"></div>'):'')+\n        '<button class=\"fin\" id=\"finalizar\"'+(CART.length?\"\":\" disabled\")+'>Finalizar pedido</button></div>';\n    }\n    var qtdTot=cartQtd();\n    document.getElementById(\"cartPane\").innerHTML=\n      '<div class=\"ctopo\"><div class=\"ctit\"><h3 class=\"serif\">Meu carrinho</h3>'+\n        '<div class=\"csub\">'+(nomeCab?('Cliente: <b>'+esc(nomeCab)+'</b> · '):'')+qtdTot+' '+(qtdTot===1?'item':'itens')+'</div>'+\n      '</div><button class=\"fechar\" onclick=\"__fecharCart()\">✕</button></div>'+\n      '<div class=\"itens\">'+itens+'</div>'+footHTML;\n    var box=document.getElementById(\"cartPane\");\n    box.querySelectorAll(\".stepper[data-ix]\").forEach(function(st){\n      var ix=Number(st.getAttribute(\"data-ix\")); var inp=st.querySelector(\"input\");\n      st.querySelectorAll(\"button\").forEach(function(b){ b.onclick=function(){ var d=Number(b.getAttribute(\"data-d\")); CART[ix].qtd=Math.max(1,(Number(CART[ix].qtd)||1)+d); salvarCart(); atualizarCartN(); renderCarrinho(); }; });\n      inp.onchange=function(){ CART[ix].qtd=Math.max(1,Number(inp.value)||1); salvarCart(); atualizarCartN(); renderCarrinho(); };\n    });\n    box.querySelectorAll(\"[data-rm]\").forEach(function(b){ b.onclick=function(){ CART.splice(Number(b.getAttribute(\"data-rm\")),1); salvarCart(); atualizarCartN(); renderCarrinho(); }; });\n    var fin=document.getElementById(\"finalizar\"); if(fin) fin.onclick=finalizarPedido;\n    var bPdf=document.getElementById(\"repPdf\"); if(bPdf) bPdf.onclick=repGerarPdfEnviar;\n    var bEsp=document.getElementById(\"repEspera\"); if(bEsp) bEsp.onclick=repDeixarEspera;\n    var bCont=document.getElementById(\"repContinuar\"); if(bCont) bCont.onclick=repContinuarComprando;\n    var bBig=document.getElementById(\"repEnviarBig\"); if(bBig) bBig.onclick=repEnviarBig;\n  }\n  function finalizarPedido(){\n    if(!CART.length) return;\n    var btn=document.getElementById(\"finalizar\"); var msg=document.getElementById(\"cmsg\");\n    var cnpjEl=document.getElementById(\"cnpjInp\"); var cnpj=(cnpjEl&&cnpjEl.value||\"\").trim();\n    var dig=cnpj.replace(/\\D+/g,\"\");\n    function erro(m){ if(msg){ msg.textContent=m; msg.style.color=\"#b91c1c\"; } }\n    if(dig.length<11){ erro(\"Digite o CNPJ (ou CPF) da sua loja para enviar o pedido.\"); if(cnpjEl) cnpjEl.focus(); return; }\n    try{ localStorage.setItem(\"bt_cnpj\", cnpj); }catch(e){}\n    var itens=CART.map(function(it){ return {cod:it.cod, medida:it.medida, corNome:it.corNome, corId:it.corId, qtd:it.qtd, preco:it.preco, regiao:it.regiao, nome:it.nome, grupo:it.grupo}; });\n    var idem=hashStr(dig+\"|\"+JSON.stringify(itens));\n    if(msg){ msg.textContent=\"\"; }\n    btn.disabled=true; btn.textContent=\"Enviando…\";\n    var extra = REP_CLIENTE ? {vendedor:(REP&&REP.nome)||\"\"} : {};\n    fetch(\"/api/loja/pedido\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(Object.assign({cnpj:cnpj, itens:itens, idem:idem}, extra))})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok, j:j||{}}; }); })\n      .then(function(res){\n        if(res.ok && res.j.ok){\n          CART=[]; salvarCart(); atualizarCartN();\n          var nome=res.j.cliente?(\", \"+esc(res.j.cliente)):\"\";\n          document.getElementById(\"cartPane\").innerHTML=\n            '<div class=\"ctopo\"><h3 class=\"serif\">🛒 Meu carrinho</h3><button class=\"fechar\" onclick=\"__fecharCart()\">✕</button></div>'+\n            '<div class=\"itens\"><div class=\"cvazio\" style=\"color:#166534;font-weight:600\">✓ '+esc(res.j.msg||\"Pedido enviado!\")+'</div>'+\n            '<div class=\"cvazio\" style=\"font-weight:400\">Obrigado'+nome+'! Qualquer dúvida, fale com a Big Tricot.</div></div>';\n        } else {\n          var m=res.j.msg||\"Não consegui enviar o pedido agora. Tente novamente.\";\n          if(res.j.detalhe&&res.j.detalhe.length){ m+=\" (\"+res.j.detalhe.join(\"; \")+\")\"; }\n          erro(m); btn.disabled=false; btn.textContent=\"Finalizar pedido\";\n        }\n      })\n      .catch(function(){ erro(\"Sem conexão no momento. Tente novamente.\"); btn.disabled=false; btn.textContent=\"Finalizar pedido\"; });\n  }\n\n  // ---------- pedido do REPRESENTANTE (espera / PDF / enviar à Big) ----------\n  function repColetarPedido(acao){\n    var itens=CART.map(function(it){ return {cod:it.cod, medida:it.medida, corNome:it.corNome, corId:it.corId, qtd:it.qtd, preco:it.preco, regiao:it.regiao, nome:it.nome, grupo:it.grupo}; });\n    var forma=document.getElementById(\"repForma\");\n    var cod_prazo=forma?forma.value:\"\";\n    var forma_desc=(forma&&forma.selectedIndex>0)?forma.options[forma.selectedIndex].text:\"\";\n    var obs=(document.getElementById(\"repObs\")||{}).value||\"\";\n    var cnpj=String((REP_CLIENTE&&REP_CLIENTE.cnpj)||\"\").replace(/\\D/g,\"\");\n    return {cnpj:cnpj, itens:itens, vendedor:(REP&&REP.nome)||\"\", acao:acao, cod_prazo:cod_prazo, forma_desc:forma_desc, observacao:obs, pedido_id:REP_PEDIDO_ID||\"\"};\n  }\n  function salvarRepPedido(acao){\n    return fetch(\"/api/loja/pedido\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(repColetarPedido(acao))})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){ if(res.ok&&res.j.ok&&res.j.pedido_id){ REP_PEDIDO_ID=res.j.pedido_id; } return res; });\n  }\n  function repNomeCli(){ return (REP_CLIENTE&&(REP_CLIENTE.nome||REP_CLIENTE.fantasia))||\"\"; }\n  function repMsg(cor,txt){ var m=document.getElementById(\"cmsg\"); if(m){ m.style.color=cor; m.innerHTML=txt; } }\n  // Gera o PDF do pedido e abre o compartilhamento (WhatsApp do próprio rep) ou baixa.\n  // No COMPUTADOR o representante quer SALVAR/IMPRIMIR → abre o PDF numa aba (tem salvar).\n  // No TABLET/CELULAR, o fluxo é mandar pelo WhatsApp → usa o compartilhar do aparelho.\n  function ehDispositivoToque(){ try{ return (navigator.maxTouchPoints||0) > 1 || /Android|iPhone|iPad|iPod|Mobile/i.test(navigator.userAgent||\"\"); }catch(e){ return false; } }\n  function repCompartilharPdf(id){\n    var cnpj=String((REP_CLIENTE&&REP_CLIENTE.cnpj)||\"\").replace(/\\D/g,\"\");\n    var url=\"/api/loja/pedido-pdf/\"+encodeURIComponent(id)+(cnpj?(\"?cnpj=\"+cnpj):\"\");\n    var nomeArq=\"pedido-\"+String(id).slice(0,8)+\".pdf\";\n    // Desktop (sem toque): abre numa aba nova pra ver/salvar/imprimir.\n    if(!ehDispositivoToque()){ try{ window.open(url,\"_blank\"); }catch(e){ location.href=url; } return Promise.resolve(); }\n    // Tablet/celular: compartilha o arquivo (WhatsApp); se não der, baixa.\n    return fetch(url).then(function(r){ if(!r.ok) throw new Error(\"pdf\"); return r.blob(); }).then(function(blob){\n      try{\n        var file=new File([blob],nomeArq,{type:\"application/pdf\"});\n        if(navigator.canShare && navigator.canShare({files:[file]})){\n          return navigator.share({files:[file], title:\"Pedido Big Tricot\", text:\"Olá! Segue o seu pedido da Big Tricot. 🧶\"}).catch(function(){});\n        }\n      }catch(e){}\n      var a=document.createElement(\"a\"); a.href=URL.createObjectURL(blob); a.download=nomeArq; document.body.appendChild(a); a.click(); a.remove();\n      try{ setTimeout(function(){ URL.revokeObjectURL(a.href); },5000); }catch(e){}\n    });\n  }\n  function repGerarPdfEnviar(){\n    if(!CART.length) return;\n    var forma=document.getElementById(\"repForma\");\n    if(!forma||!forma.value){ repMsg(\"#b91c1c\",\"Escolha a forma de pagamento primeiro.\"); return; }\n    var b=document.getElementById(\"repPdf\"); if(b){ b.disabled=true; b.textContent=\"Gerando PDF…\"; }\n    repMsg(\"#666\",\"\");\n    salvarRepPedido(\"espera\").then(function(res){\n      if(!(res.ok&&res.j.ok&&res.j.pedido_id)){ if(b){b.disabled=false;b.textContent=\"📄 Gerar PDF e enviar ao cliente\";} repMsg(\"#b91c1c\",(res.j&&res.j.msg)||\"Não consegui salvar o pedido.\"); return; }\n      return repCompartilharPdf(res.j.pedido_id).then(function(){\n        if(b){ b.disabled=false; b.textContent=\"📄 Gerar PDF e enviar ao cliente\"; }\n        repMsg(\"#166534\",\"PDF gerado! Depois do OK do cliente, toque em ✅ Enviar à Big.\");\n      });\n    }).catch(function(){ if(b){b.disabled=false;b.textContent=\"📄 Gerar PDF e enviar ao cliente\";} repMsg(\"#b91c1c\",\"Sem conexão. Tente de novo.\"); });\n  }\n  // \"Continuar comprando\": só fecha o carrinho e volta ao catálogo com o MESMO cliente.\n  // NÃO salva pedido nem gera número — os itens ficam no mesmo carrinho (mesmo pedido em\n  // andamento). Guarda a forma/observação já digitadas pra não perder ao reabrir.\n  function repContinuarComprando(){\n    var f=document.getElementById(\"repForma\"); if(f) REP_PEDIDO_FORMA=f.value||\"\";\n    var o=document.getElementById(\"repObs\"); if(o) REP_PEDIDO_OBS=o.value||\"\";\n    __fecharCart();\n  }\n  function repDeixarEspera(){\n    if(!CART.length) return;\n    var b=document.getElementById(\"repEspera\"); if(b){ b.disabled=true; b.textContent=\"Salvando…\"; }\n    repMsg(\"#666\",\"\");\n    salvarRepPedido(\"espera\").then(function(res){\n      if(b){ b.disabled=false; b.textContent=\"⏸️ Deixar em espera\"; }\n      if(res.ok&&res.j.ok){ CART=[]; salvarCart(); atualizarCartN();\n        repTelaOk(\"⏸️ Pedido em espera\",\"Guardamos o pedido de <b>\"+esc(repNomeCli())+\"</b>. Você pode gerar o PDF e enviar ao cliente quando quiser.\");\n      } else { repMsg(\"#b91c1c\",(res.j&&res.j.msg)||\"Não consegui salvar.\"); }\n    }).catch(function(){ if(b){b.disabled=false;b.textContent=\"⏸️ Deixar em espera\";} repMsg(\"#b91c1c\",\"Sem conexão. Tente de novo.\"); });\n  }\n  function repEnviarBig(){\n    if(!CART.length) return;\n    var forma=document.getElementById(\"repForma\");\n    if(!forma||!forma.value){ repMsg(\"#b91c1c\",\"Escolha a forma de pagamento antes de enviar.\"); return; }\n    if(!confirm(\"Enviar este pedido para a Big Tricot?\\nDepois de enviado ele trava — pra mexer você precisa pedir liberação.\")) return;\n    var b=document.getElementById(\"repEnviarBig\"); if(b){ b.disabled=true; b.textContent=\"Enviando…\"; }\n    repMsg(\"#666\",\"\");\n    salvarRepPedido(\"enviar\").then(function(res){\n      if(res.ok&&res.j.ok){ CART=[]; salvarCart(); atualizarCartN();\n        repTelaOk(\"✅ Pedido enviado!\",\"O pedido de <b>\"+esc(repNomeCli())+\"</b> foi enviado. A Big Tricot vai conferir e aprovar — aí ele entra no Syntech com o seu código.\");\n      } else { if(b){b.disabled=false;b.textContent=\"✅ Enviar à Big\";} repMsg(\"#b91c1c\",(res.j&&res.j.msg)||\"Não consegui enviar.\"); }\n    }).catch(function(){ if(b){b.disabled=false;b.textContent=\"✅ Enviar à Big\";} repMsg(\"#b91c1c\",\"Sem conexão. Tente de novo.\"); });\n  }\n  function repTelaOk(titulo, html){\n    document.getElementById(\"cartPane\").innerHTML=\n      '<div class=\"ctopo\"><h3 class=\"serif\">🛒 Meu carrinho</h3><button class=\"fechar\" onclick=\"__fecharCart()\">✕</button></div>'+\n      '<div class=\"itens\"><div style=\"padding:18px 6px;text-align:center\">'+\n      '<div style=\"font-size:19px;font-weight:800;color:#166534;margin-bottom:10px\">'+esc(titulo)+'</div>'+\n      '<div style=\"font-size:14px;color:#555;line-height:1.55\">'+html+'</div>'+\n      (REP_PEDIDO_ID?('<button id=\"repOkPdf\" style=\"display:block;width:100%;box-sizing:border-box;border:0;border-radius:10px;padding:13px;font-size:14px;font-weight:600;cursor:pointer;color:#fff;background:#2c3e50;margin-top:18px\">📄 Gerar PDF e enviar ao cliente</button>'):'')+\n      '<button id=\"repOkVoltar\" style=\"display:block;width:100%;box-sizing:border-box;border:0;border-radius:10px;padding:13px;font-size:14px;font-weight:600;cursor:pointer;color:#fff;background:#8a8073;margin-top:8px\">Voltar ao menu</button>'+\n      '</div></div>';\n    var p=document.getElementById(\"repOkPdf\"); if(p) p.onclick=function(){ repCompartilharPdf(REP_PEDIDO_ID); };\n    var v=document.getElementById(\"repOkVoltar\"); if(v) v.onclick=function(){ __fecharCart(); __repVoltarArea(); };\n  }\n\n  // ---------- eventos globais ----------\n  document.getElementById(\"app\").addEventListener(\"click\",function(e){ var el=e.target.closest(\".prod\"); if(el) abrir(el.getAttribute(\"data-id\")); });\n  document.getElementById(\"modal\").addEventListener(\"click\",function(e){ if(e.target.id===\"modal\") window.__fechar(); });\n  document.getElementById(\"cart\").addEventListener(\"click\",function(e){ if(e.target.id===\"cart\") window.__fecharCart(); });\n  document.getElementById(\"abrirCart\").addEventListener(\"click\",abrirCarrinho);\n  document.getElementById(\"meus\").addEventListener(\"click\",function(e){ if(e.target===this) __fecharMeus(); });\n  (function(){ var mb=document.getElementById(\"abrirMeus\"); if(mb) mb.addEventListener(\"click\",abrirMeus); })();\n  document.getElementById(\"q\").addEventListener(\"input\",function(){ filtroTxt=this.value; render(); });\n  // Rola até o INÍCIO da categoria descontando a altura das barras fixas (busca + categorias),\n  // pra o título da seção não ficar escondido atrás delas (ex.: no celular).\n  function irParaSecao(id){\n    var t=document.getElementById(id); if(!t) return;\n    var bf=document.querySelector(\".buscafaixa\"); var cb=document.querySelector(\".cats-bar\");\n    var off=(bf?bf.offsetHeight:0)+(cb&&cb.offsetParent!==null?cb.offsetHeight:0)+8;\n    var y=t.getBoundingClientRect().top + (window.pageYOffset||document.documentElement.scrollTop||0) - off;\n    try{ window.scrollTo({top:Math.max(0,y), behavior:\"smooth\"}); }catch(e){ window.scrollTo(0,Math.max(0,y)); }\n  }\n  document.getElementById(\"abas\").addEventListener(\"click\",function(e){ var a=e.target.closest(\"a\"); if(!a)return; irParaSecao(a.getAttribute(\"data-sec\")); });\n  document.getElementById(\"cats\").addEventListener(\"click\",function(e){ var b=e.target.closest(\"button[data-sec]\"); if(!b)return; irParaSecao(b.getAttribute(\"data-sec\")); });\n\n  try{ var r=document.getElementById(\"rodape\"); var n=PRODUTOS.length; var d=D.estoque&&D.estoque.atualizadoMs? new Date(D.estoque.atualizadoMs):new Date(); r.textContent=n+\" produtos · atualizado em \"+d.toLocaleDateString(\"pt-BR\"); }catch(e){}\n\n  // ---------- ENTRADA / SESSÃO DO CLIENTE (CNPJ) ----------\n  // A região de preço (Sul/Norte) vem do cadastro do cliente — o cliente NÃO escolhe.\n  function cliSalvo(){ try{ return JSON.parse(localStorage.getItem(\"bt_cli\")||\"null\"); }catch(e){ return null; } }\n  function mostrarSaudacao(nome){\n    var el=document.getElementById(\"saudacao\"); if(!el) return;\n    if(nome){ el.style.display=\"flex\"; el.innerHTML='Olá, <b style=\"color:#fff\">'+esc(nome)+'</b> · <a href=\"#\" id=\"sairLoja\" style=\"color:#e7a187;text-decoration:none\">sair</a>';\n      var s=document.getElementById(\"sairLoja\"); if(s) s.onclick=function(ev){ ev.preventDefault(); sairLoja(); };\n    } else { el.style.display=\"none\"; el.innerHTML=\"\"; }\n  }\n  function aplicarSessao(nome,reg,liberado){\n    regiao = (reg===\"norte\")?\"norte\":\"sul\";\n    LIBERADO = !!liberado;\n    try{ localStorage.setItem(\"bt_cli\", JSON.stringify({nome:nome||\"\", regiao:regiao, liberado:LIBERADO})); }catch(e){}\n    mostrarSaudacao(nome);\n    document.getElementById(\"entrada\").style.display=\"none\";\n    document.body.style.overflow=\"\";\n    atualizarAvisoLib();\n    render(); if(document.getElementById(\"modal\").classList.contains(\"show\")) renderDetalhe();\n  }\n  // Faixa de aviso no topo pra cliente em análise (preços/pedidos ainda bloqueados).\n  function atualizarAvisoLib(){\n    var el=document.getElementById(\"avisoLib\"); if(!el) return;\n    if(cnpjSalvo() && !LIBERADO){ el.style.display=\"block\"; el.innerHTML='🔒 Seu cadastro está <b>em análise</b>. Você já pode navegar o catálogo; os <b>preços e pedidos</b> liberam assim que a Big Tricot aprovar seu acesso.'; }\n    else { el.style.display=\"none\"; }\n  }\n  function ehPortalRep(){ try{ return document.documentElement.classList.contains(\"portal-rep\") || new URLSearchParams(location.search).get(\"rep\")===\"1\"; }catch(e){ return false; } }\n  function abrirEntrada(){\n    var ov=document.getElementById(\"entrada\"); ov.style.display=\"flex\"; document.body.style.overflow=\"hidden\";\n    // ✕ só no catálogo do cliente (dá pra fechar e navegar). No portal do rep não há catálogo atrás.\n    var fx=document.getElementById(\"entFechar\"); if(fx) fx.style.display=ehPortalRep()?\"none\":\"flex\";\n    var inp=document.getElementById(\"entCnpj\"); if(inp && !inp.value) inp.value=cnpjSalvo();\n    setTimeout(function(){ try{ inp.focus(); }catch(e){} },50);\n  }\n  // Fecha o login e deixa o cliente navegar pelo catálogo (sem logar).\n  function fecharEntrada(){ var ov=document.getElementById(\"entrada\"); if(ov) ov.style.display=\"none\"; document.body.style.overflow=\"\"; }\n  (function(){\n    var fx=document.getElementById(\"entFechar\"); if(fx) fx.addEventListener(\"click\",fecharEntrada);\n    var ov=document.getElementById(\"entrada\");\n    if(ov) ov.addEventListener(\"click\",function(e){ if(e.target===ov && !ehPortalRep()) fecharEntrada(); });\n    document.addEventListener(\"keydown\",function(e){ if(e.key===\"Escape\"){ var o=document.getElementById(\"entrada\"); if(o && o.style.display!==\"none\" && !ehPortalRep()) fecharEntrada(); } });\n  })();\n  function sairLoja(){ try{ localStorage.removeItem(\"bt_cli\"); localStorage.removeItem(\"bt_cnpj\"); }catch(e){} LIBERADO=false; TOKEN_ACESSO=\"\"; mostrarSaudacao(\"\"); atualizarAvisoLib(); render(); mostrarEnt(); abrirEntrada(); }\n  function entrarLoja(){\n    var inp=document.getElementById(\"entCnpj\"); var inps=document.getElementById(\"entSenha\"); var msg=document.getElementById(\"entMsg\"); var btn=document.getElementById(\"entBtn\");\n    var cnpj=(inp&&inp.value||\"\").trim(); var dig=cnpj.replace(/\\D+/g,\"\"); var senha=(inps&&inps.value||\"\");\n    if(dig.length<11){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Digite o CNPJ (ou CPF) da sua loja.\"; return; }\n    if(!senha){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Digite sua senha.\"; return; }\n    msg.textContent=\"\"; btn.disabled=true; btn.textContent=\"Entrando…\";\n    fetch(\"/api/loja/entrar\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({cnpj:cnpj,senha:senha})})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        btn.disabled=false; btn.textContent=\"Entrar\";\n        if(res.ok && res.j.ok){ try{ localStorage.setItem(\"bt_cnpj\", cnpj); }catch(e){} aplicarSessao(res.j.nome, res.j.regiao, res.j.liberado); }\n        else if(res.j.erro===\"cliente_nao_encontrado\"){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Não encontramos esse CNPJ. Se é sua primeira vez, cadastre sua loja abaixo 👇\"; }\n        else if(res.j.erro===\"sem_senha\"){ msg.style.color=\"#b91c1c\"; msg.innerHTML=\"Seu acesso ainda não tem senha. Abra o <b>link que a Big Tricot te enviou</b> para criar sua senha.\"; }\n        else { msg.style.color=\"#b91c1c\"; msg.textContent=res.j.msg||\"Não consegui entrar. Confira o CNPJ e a senha.\"; }\n      })\n      .catch(function(){ btn.disabled=false; btn.textContent=\"Entrar\"; msg.style.color=\"#b91c1c\"; msg.textContent=\"Sem conexão no momento. Tente novamente.\"; });\n  }\n  document.getElementById(\"entBtn\").addEventListener(\"click\",entrarLoja);\n  document.getElementById(\"entSenha\").addEventListener(\"keydown\",function(e){ if(e.key===\"Enter\") entrarLoja(); });\n\n  // Criar/definir senha (via link de acesso com token, ou trocar depois de logado)\n  var TOKEN_ACESSO=\"\", TOKEN_REP=\"\";\n  function mostrarCriarSenha(nome, cnpjMascara){\n    document.getElementById(\"entView\").style.display=\"none\";\n    document.getElementById(\"cadView\").style.display=\"none\";\n    document.getElementById(\"repView\").style.display=\"none\";\n    document.getElementById(\"senhaView\").style.display=\"block\";\n    var quem = TOKEN_REP ? 'Crie a sua senha de representante.' : (nome ? ('Olá, <b>'+esc(nome)+'</b>'+(cnpjMascara?' · CNPJ '+esc(cnpjMascara):'')+'. Crie uma senha para acessar o catálogo.') : 'Crie uma senha para acessar o catálogo.');\n    document.getElementById(\"senhaQuem\").innerHTML = TOKEN_REP && nome ? ('Olá, <b>'+esc(nome)+'</b>. '+quem) : quem;\n    document.getElementById(\"snMsg\").textContent=\"\";\n    var ov=document.getElementById(\"entrada\"); ov.style.display=\"flex\"; document.body.style.overflow=\"hidden\";\n  }\n  function salvarNovaSenha(){\n    var nova=(document.getElementById(\"snNova\").value||\"\"); var conf=(document.getElementById(\"snConf\").value||\"\");\n    var msg=document.getElementById(\"snMsg\"), btn=document.getElementById(\"snBtn\");\n    if(nova.length<4){ msg.style.color=\"#b91c1c\"; msg.textContent=\"A senha precisa ter pelo menos 4 caracteres.\"; return; }\n    if(nova!==conf){ msg.style.color=\"#b91c1c\"; msg.textContent=\"As senhas não são iguais.\"; return; }\n    msg.textContent=\"\"; btn.disabled=true; btn.textContent=\"Salvando…\";\n    var ehRep = !!TOKEN_REP;\n    var url = ehRep ? \"/api/loja/rep-definir-senha\" : \"/api/loja/definir-senha\";\n    var body = ehRep ? {token:TOKEN_REP, nova:nova} : (TOKEN_ACESSO ? {token:TOKEN_ACESSO, nova:nova} : {cnpj:cnpjSalvo(), nova:nova});\n    fetch(url,{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body)})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        btn.disabled=false; btn.textContent=\"Salvar e entrar\";\n        if(res.ok && res.j.ok){\n          try{ history.replaceState(null,\"\",location.pathname); }catch(e){}\n          if(ehRep){ TOKEN_REP=\"\"; aplicarRep(res.j.rep, res.j.clientes); }\n          else { try{ if(res.j.cnpj) localStorage.setItem(\"bt_cnpj\", res.j.cnpj); }catch(e){} aplicarSessao(res.j.nome, res.j.regiao, res.j.liberado); }\n        }\n        else { msg.style.color=\"#b91c1c\"; msg.textContent=res.j.msg||\"Não consegui salvar a senha.\"; }\n      })\n      .catch(function(){ btn.disabled=false; btn.textContent=\"Salvar e entrar\"; msg.style.color=\"#b91c1c\"; msg.textContent=\"Sem conexão. Tente de novo.\"; });\n  }\n  document.getElementById(\"snBtn\").addEventListener(\"click\",salvarNovaSenha);\n\n  // ── REPRESENTANTE (R1): login + carteira ──\n  function repSalvo(){ try{ return JSON.parse(localStorage.getItem(\"bt_rep\")||\"null\"); }catch(e){ return null; } }\n  function mostrarRepView(){ try{ document.documentElement.classList.add(\"portal-rep\"); }catch(e){} var rb=document.getElementById(\"repBoot\"); if(rb) rb.style.display=\"\"; /* mantém a cobertura: o catálogo do lojista NÃO aparece atrás do login do rep */ [\"entView\",\"cadView\",\"senhaView\"].forEach(function(id){ var e=document.getElementById(id); if(e) e.style.display=\"none\"; }); document.getElementById(\"repView\").style.display=\"block\"; document.getElementById(\"repMsg\").textContent=\"\"; var ov=document.getElementById(\"entrada\"); ov.style.display=\"flex\"; document.body.style.overflow=\"hidden\"; var i=document.getElementById(\"repEmail\"); setTimeout(function(){ try{ i.focus(); }catch(e){} },50); }\n  function repEntrar(){\n    var email=(document.getElementById(\"repEmail\").value||\"\").trim(); var senha=(document.getElementById(\"repSenha\").value||\"\");\n    var msg=document.getElementById(\"repMsg\"), btn=document.getElementById(\"repBtn\");\n    if(!email){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Digite seu e-mail.\"; return; }\n    if(!senha){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Digite sua senha.\"; return; }\n    msg.textContent=\"\"; btn.disabled=true; btn.textContent=\"Entrando…\";\n    fetch(\"/api/loja/rep-entrar\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({email:email,senha:senha})})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        btn.disabled=false; btn.textContent=\"Entrar\";\n        if(res.ok && res.j.ok){ aplicarRep(res.j.rep, res.j.clientes); }\n        else if(res.j.erro===\"sem_senha\"){ msg.style.color=\"#b91c1c\"; msg.innerHTML=\"Seu acesso ainda não tem senha. Abra o <b>link que a Big Tricot te enviou</b>.\"; }\n        else { msg.style.color=\"#b91c1c\"; msg.textContent=res.j.msg||\"Não consegui entrar. Confira e-mail e senha.\"; }\n      })\n      .catch(function(){ btn.disabled=false; btn.textContent=\"Entrar\"; msg.style.color=\"#b91c1c\"; msg.textContent=\"Sem conexão. Tente de novo.\"; });\n  }\n  var REP=null, REP_CLIENTES=[], REP_CLIENTE=null, REP_NOVO_CNPJ=\"\";\n  var REP_PRAZOS=[], REP_PEDIDO_ID=\"\", REP_PEDIDO_FORMA=\"\", REP_PEDIDO_OBS=\"\";  // formas de pagamento (prazos) + rascunho atual do rep\n  var REP_SOVER=false;  // catálogo em modo \"só visualização\" (rep vê produtos/preços, sem montar pedido)\n  function aplicarRep(rep, clientes){\n    if(!rep) return;\n    REP=rep; REP_CLIENTES=clientes||[];\n    try{ localStorage.setItem(\"bt_rep\", JSON.stringify(rep)); }catch(e){}\n    // Portal do representante é separado do catálogo do cliente: fixa ?rep=1 na URL\n    // pra que recarregar continue na área do rep (e o /loja puro fique sendo do cliente).\n    try{ if(new URLSearchParams(location.search).get(\"rep\")!==\"1\") history.replaceState(null,\"\",location.pathname+\"?rep=1\"); }catch(e){}\n    var rb=document.getElementById(\"repBoot\"); if(rb) rb.style.display=\"none\";\n    document.getElementById(\"entrada\").style.display=\"none\";\n    document.getElementById(\"repArea\").style.display=\"block\";\n    document.body.style.overflow=\"\";\n    document.getElementById(\"repNome\").textContent=rep.nome||\"\";\n    document.getElementById(\"repOla\").textContent=(String(rep.nome||\"\").split(\" \")[0]||\"\");\n    document.getElementById(\"repTileCount\").textContent=REP_CLIENTES.length+\" cliente\"+(REP_CLIENTES.length===1?\"\":\"s\");\n    __repHome();\n  }\n  // Mini painel de vendas: busca os números reais do rep e desenha o gráfico de barras.\n  function carregarRepVendas(){\n    if(!REP||!REP.id) return;\n    var host=document.getElementById(\"rdChart\"); if(!host) return;\n    fetch(\"/api/loja/rep-vendas?rep=\"+encodeURIComponent(REP.id))\n      .then(function(r){ return r.json(); })\n      .then(function(j){\n        if(!j||!j.ok){ host.innerHTML='<div class=\"rd-empty\">Não consegui carregar as vendas agora.</div>'; return; }\n        var mv=document.getElementById(\"rdVendaMes\"); if(mv) mv.textContent=brl((j.mes_atual&&j.mes_atual.valor)||0);\n        var mp=document.getElementById(\"rdPedMes\"); if(mp) mp.textContent=String((j.mes_atual&&j.mes_atual.pedidos)||0);\n        renderRepChart(j.meses||[]);\n      }).catch(function(){ host.innerHTML='<div class=\"rd-empty\">Não consegui carregar as vendas agora.</div>'; });\n  }\n  var REP_VENDAS_MESES=null, REP_VENDAS_RT=null;\n  window.addEventListener(\"resize\",function(){ if(!REP_VENDAS_MESES) return; clearTimeout(REP_VENDAS_RT); REP_VENDAS_RT=setTimeout(function(){ renderRepChart(REP_VENDAS_MESES); },180); });\n  function renderRepChart(meses){\n    REP_VENDAS_MESES=meses;\n    var host=document.getElementById(\"rdChart\"); if(!host) return;\n    var n=meses.length; var max=0;\n    meses.forEach(function(m){ var v=Number(m.valor)||0; if(v>max) max=v; });\n    if(!n || max<=0){ host.innerHTML='<div class=\"rd-empty\">Sem vendas registradas ainda.<br>Seus pedidos efetuados aparecem aqui.</div>'; return; }\n    var W=Math.max(220, Math.round(host.clientWidth||300)), H=138, padT=8, padB=20;\n    var gap=Math.max(7, Math.round(W*0.03)); var bw=(W-gap*(n-1))/n;\n    var parts=\"\";\n    for(var i=0;i<n;i++){\n      var m=meses[i], v=Number(m.valor)||0;\n      var h=Math.max(2, (v/max)*(H-padT-padB));\n      var x=i*(bw+gap), y=H-padB-h, cur=(i===n-1)?\" cur\":\"\";\n      var tip=String(m.label||\"\").toUpperCase()+\": \"+brl(v)+\" · \"+(Number(m.pedidos)||0)+\" ped.\";\n      parts+='<rect class=\"rd-bar'+cur+'\" x=\"'+x.toFixed(1)+'\" y=\"'+y.toFixed(1)+'\" width=\"'+bw.toFixed(1)+'\" height=\"'+h.toFixed(1)+'\" rx=\"3\"><title>'+esc(tip)+'</title></rect>';\n      parts+='<text class=\"rd-xl\" x=\"'+(x+bw/2).toFixed(1)+'\" y=\"'+(H-6)+'\" text-anchor=\"middle\">'+esc(m.label||\"\")+'</text>';\n    }\n    host.innerHTML='<svg width=\"'+W+'\" height=\"'+H+'\" viewBox=\"0 0 '+W+' '+H+'\" role=\"img\" aria-label=\"Vendas dos últimos 6 meses\">'+parts+'</svg>';\n  }\n  var REP_SUBS=[\"repHome\",\"repCartView\",\"repMontar\",\"repNovoCli\",\"repNovoOk\",\"repPedidos\"];\n  function repMostrarSub(id){ REP_SUBS.forEach(function(s){ var e=document.getElementById(s); if(e) e.style.display=(s===id)?\"block\":\"none\"; }); try{ document.getElementById(\"repArea\").scrollTop=0; }catch(e){} }\n  window.__repHome=function(){ repMostrarSub(\"repHome\"); carregarRepVendas(); };\n  window.__repEscolher=function(){ __repSecao(\"carteira\"); };\n  window.__repSecao=function(sec){\n    if(sec===\"carteira\"){ document.getElementById(\"repCartTit\").innerHTML='Minha carteira <span class=\"rep-count\" id=\"repCount\"></span>'; document.getElementById(\"repCartDica\").textContent=\"Toque num cliente para montar o pedido dele.\"; var rb=document.getElementById(\"repBusca\"); if(rb) rb.value=\"\"; repMostrarSub(\"repCartView\"); renderCarteira(REP_CLIENTES); return; }\n    if(sec===\"montar\"){ repMostrarSub(\"repMontar\"); return; }\n    if(sec===\"novo\"){ document.getElementById(\"rncMsg\").textContent=\"\"; repMostrarSub(\"repNovoCli\"); return; }\n    if(sec===\"produtos\"){ iniciarRepVerProdutos(); return; }\n    if(sec===\"pedidos\"){ repMostrarSub(\"repPedidos\"); carregarRepPedidos(); return; }\n    var nomes={avisos:\"Avisos\"};\n    alert(\"“\"+(nomes[sec]||sec)+\"” está chegando! 🧶\\nEstamos liberando a área do representante por etapas.\");\n  };\n  function fmtDataCurta(s){\n    var m=String(s||\"\").match(/(\\d{4})-(\\d{2})-(\\d{2})/);\n    return m ? (m[3]+\"/\"+m[2]+\"/\"+m[1]) : \"\";\n  }\n  function renderCarteira(clientes){\n    REP_CLIENTES=clientes||REP_CLIENTES;\n    document.getElementById(\"repCount\").textContent=\"· \"+REP_CLIENTES.length+\" cliente\"+(REP_CLIENTES.length===1?\"\":\"s\");\n    desenharCarteira();\n  }\n  function desenharCarteira(){\n    var termo=(document.getElementById(\"repBusca\").value||\"\").trim().toLowerCase();\n    var dig=termo.replace(/\\D/g,\"\");\n    var box=document.getElementById(\"repCarteira\");\n    if(!REP_CLIENTES.length){ box.innerHTML='<div class=\"rep-vazio\">Você ainda não tem clientes na carteira. Fale com a Big Tricot.</div>'; return; }\n    var lista=REP_CLIENTES.filter(function(c){\n      if(!termo) return true;\n      var nome=(c.nome||c.fantasia||\"\").toLowerCase();\n      var cid=((c.cidade||\"\")+\" \"+(c.uf||\"\")).toLowerCase();\n      var cnpjD=String(c.cnpj||\"\").replace(/\\D/g,\"\");\n      return nome.indexOf(termo)>=0 || cid.indexOf(termo)>=0 || (dig.length>=2 && cnpjD.indexOf(dig)>=0);\n    });\n    if(!lista.length){ box.innerHTML='<div class=\"rep-vazio\">Nenhum cliente encontrado para “'+esc(termo)+'”.</div>'; return; }\n    var calSvg='<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><rect x=\"3\" y=\"4\" width=\"18\" height=\"18\" rx=\"2\"/><path d=\"M16 2v4M8 2v4M3 10h18\"/></svg>';\n    box.innerHTML=lista.map(function(c){\n      var cidade=[c.cidade,c.uf].filter(Boolean).join(\"/\");\n      var chip = c.bloqueado ? '<span class=\"rep-chip block\">● Bloqueado</span>'\n        : c.liberado ? '<span class=\"rep-chip ok\">● Liberado</span>'\n        : '<span class=\"rep-chip wait\">● Em análise</span>';\n      var dt=fmtDataCurta(c.ultimo_pedido);\n      var ped=dt ? ('<div class=\"ped\">'+calSvg+'Último pedido: <b>'+dt+'</b></div>')\n                 : '<div class=\"ped\">'+calSvg+'Sem pedidos ainda</div>';\n      return '<button class=\"rep-row\" onclick=\"__repCliente(\\''+esc(c.id)+'\\')\">'+\n        '<div class=\"ri\"><div class=\"nm\">'+esc(c.nome||c.fantasia||\"(sem nome)\")+'</div>'+\n        '<div class=\"sub\">'+(c.cnpj?esc(c.cnpj):'sem CNPJ')+(cidade?' · '+esc(cidade):'')+'</div>'+ped+'</div>'+\n        '<div class=\"rr\">'+chip+'<svg class=\"chev\" viewBox=\"0 0 24 24\" aria-hidden=\"true\"><path d=\"m9 18 6-6-6-6\"/></svg></div></button>';\n    }).join(\"\");\n  }\n  // ---- Meus pedidos do representante (em espera + enviados) ----\n  function carregarRepPedidos(){\n    var box=document.getElementById(\"repPedLista\");\n    box.innerHTML='<div class=\"rep-vazio\">Carregando…</div>';\n    if(!REP_PRAZOS.length){ fetch(\"/api/loja/prazos\").then(function(r){return r.json();}).then(function(j){ if(Array.isArray(j)) REP_PRAZOS=j; }).catch(function(){}); }\n    fetch(\"/api/loja/rep-pedidos?rep=\"+encodeURIComponent((REP&&REP.id)||\"\"))\n      .then(function(r){ return r.json(); })\n      .then(function(j){ renderRepPedidos((j&&j.pedidos)||[]); })\n      .catch(function(){ box.innerHTML='<div class=\"rep-vazio\">Não consegui carregar seus pedidos. Tente de novo.</div>'; });\n  }\n  function chipPed(st,label){\n    var cls = st===\"espera\"?\"wait\" : st===\"aguardando\"?\"info\" : (st===\"aprovado\"||st===\"syntech\")?\"ok\" : st===\"erro\"?\"block\":\"info\";\n    return '<span class=\"rep-chip '+cls+'\">● '+esc(label)+'</span>';\n  }\n  var REP_PED_LISTA=[], REP_PED_ABERTO=\"\";\n  function renderRepPedidos(lista){\n    if(lista) REP_PED_LISTA=lista;\n    var box=document.getElementById(\"repPedLista\");\n    if(!REP_PED_LISTA.length){ box.innerHTML='<div class=\"rep-vazio\">Você ainda não tem pedidos. Toque em <b>Novo pedido</b> pra começar.</div>'; return; }\n    box.innerHTML=REP_PED_LISTA.map(function(p){\n      var aberto=REP_PED_ABERTO===p.id;\n      var dt=fmtDataCurta(p.data);\n      var resumo=(p.pecas||0)+\" peça\"+((p.pecas===1)?\"\":\"s\")+\" · \"+brl(p.total||0)+(dt?(\" · \"+dt):\"\");\n      return '<div class=\"rped'+(aberto?\" open\":\"\")+'\">'+\n        '<button class=\"rped-h\" onclick=\"__repPedToggle(\\''+esc(p.id)+'\\')\">'+\n          '<span class=\"rped-hi\"><span class=\"rped-cli\">'+esc(p.cliente||\"(cliente)\")+'</span><span class=\"rped-res\">'+esc(resumo)+'</span></span>'+\n          chipPed(p.status,p.label)+'<span class=\"rped-chev\">'+chevSvg()+'</span>'+\n        '</button>'+\n        '<div class=\"rped-det\" id=\"rpd-'+esc(p.id)+'\"></div>'+\n      '</div>';\n    }).join(\"\");\n    if(REP_PED_ABERTO) carregarRepPedDet(REP_PED_ABERTO);\n  }\n  window.__repPedToggle=function(id){ REP_PED_ABERTO=(REP_PED_ABERTO===id)?\"\":id; renderRepPedidos(); };\n  function carregarRepPedDet(id){\n    var el=document.getElementById(\"rpd-\"+id); if(!el) return;\n    el.innerHTML='<div class=\"rep-vazio\" style=\"padding:12px\">Carregando itens…</div>';\n    fetch(\"/api/loja/rep-pedido-detalhe?id=\"+encodeURIComponent(id)+\"&rep=\"+encodeURIComponent((REP&&REP.id)||\"\"))\n      .then(function(r){ return r.json(); })\n      .then(function(d){ if(!d||!d.ok){ el.innerHTML='<div class=\"rep-vazio\" style=\"padding:12px\">Não consegui carregar os itens.</div>'; return; } el.innerHTML=renderRepPedDet(d,id); })\n      .catch(function(){ el.innerHTML='<div class=\"rep-vazio\" style=\"padding:12px\">Sem conexão. Tente de novo.</div>'; });\n  }\n  function renderRepPedDet(d,id){\n    var linhas=(d.itens||[]).map(function(it){\n      return '<tr><td class=\"c-prod\" title=\"'+esc(it.produto)+'\">'+esc(it.produto)+'</td>'+\n        '<td class=\"c-desc\" title=\"'+esc(it.descricao||\"\")+'\">'+esc(it.descricao||\"—\")+'</td>'+\n        '<td class=\"c-qtd\">'+(Number(it.qtd)||0)+'x</td>'+\n        '<td class=\"c-val\">'+brl(it.valor_unit||0)+'</td>'+\n        '<td class=\"c-val\">'+brl(it.valor_total||0)+'</td></tr>';\n    }).join(\"\");\n    var tbl=(d.itens&&d.itens.length)\n      ? '<table class=\"ctbl pedtbl\"><thead><tr><th class=\"c-prod\">Produto</th><th class=\"c-desc\">Descrição</th><th class=\"c-qtd\">Qtde</th><th class=\"c-val\">Vlr unit.</th><th class=\"c-val\">Vlr total</th></tr></thead><tbody>'+linhas+'</tbody></table>'\n      : '<div class=\"rep-vazio\" style=\"padding:10px\">Sem itens.</div>';\n    var grid='<div class=\"rped-grid\">'+\n      '<div><span>Status</span>'+chipPed(d.status,d.label)+'</div>'+\n      '<div><span>Pedido</span><b>'+esc(d.numero)+'</b></div>'+\n      '<div><span>Data/hora</span><b>'+esc(fmtDataHora(d.data))+'</b></div>'+\n      '<div><span>Peças</span><b>'+(Number(d.pecas)||0)+'</b></div>'+\n      '<div><span>Valor total</span><b class=\"rped-tot\">'+brl(d.total||0)+'</b></div>'+\n    '</div>';\n    var acoes='<div class=\"rep-ped-acoes\">'+\n      '<button class=\"prim\" onclick=\"__repPedPdf(\\''+esc(id)+'\\')\">📄 Baixar PDF</button>'+\n      (d.editavel?('<button onclick=\"__repReabrir(\\''+esc(id)+'\\')\">✏️ Reabrir / adicionar itens</button>'+\n                   '<button class=\"go\" onclick=\"__repPedEnviar(\\''+esc(id)+'\\',\\''+(d.forma?\"1\":\"\")+'\\')\">✅ Enviar à Big</button>'+\n                   '<button class=\"del\" onclick=\"__repPedExcluir(\\''+esc(id)+'\\')\">Excluir</button>'):'')+\n      '</div>';\n    return '<div class=\"rped-body\">'+grid+tbl+acoes+'</div>';\n  }\n  // Baixar/ver o PDF: abre numa aba nova (dá pra salvar, imprimir ou compartilhar de lá).\n  window.__repPedPdf=function(id){ var url=\"/api/loja/pedido-pdf/\"+encodeURIComponent(id); try{ window.open(url,\"_blank\"); }catch(e){ location.href=url; } };\n  // Recompõe um item salvo (cod/medida/cor) nas chaves do catálogo (pid/grupo/id_tamanho/corId),\n  // pra ele casar com o catálogo ao reabrir (somar quantidade ao adicionar o mesmo produto de novo).\n  function reconstruirItemCart(it){\n    var base={pid:\"\", nome:it.nome, grupo:it.grupo||\"\", cod:it.cod, id_tamanho:\"\", medida:it.medida, corId:\"\", corNome:it.corNome, preco:it.preco, regiao:it.regiao, qtd:it.qtd};\n    try{\n      for(var pi=0; pi<PRODUTOS.length; pi++){\n        var p=PRODUTOS[pi], gs=p.grupos||[];\n        for(var gi=0; gi<gs.length; gi++){\n          var g=gs[gi], ls=g.linhas||[];\n          for(var li=0; li<ls.length; li++){\n            if(String(ls[li].cod)===String(it.cod)){\n              base.pid=p.id; base.grupo=g.titulo||base.grupo; base.id_tamanho=ls[li].id_tamanho; base.medida=medidaDe(ls[li].id_tamanho)||it.medida;\n              var cores=p.cores||[];\n              for(var ci=0; ci<cores.length; ci++){ if(String(cores[ci].nome||\"\").trim().toLowerCase()===String(it.corNome||\"\").trim().toLowerCase()){ base.corId=cores[ci].id_cor; break; } }\n              return base;\n            }\n          }\n        }\n      }\n    }catch(e){}\n    return base;\n  }\n  // Reabrir um pedido EM ESPERA no catálogo pra adicionar mais itens (atualiza o mesmo rascunho).\n  window.__repReabrir=function(id){\n    fetch(\"/api/loja/rep-pedido-itens?id=\"+encodeURIComponent(id)+\"&rep=\"+encodeURIComponent((REP&&REP.id)||\"\"))\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        if(!(res.ok && res.j.ok)){ alert((res.j&&res.j.msg)||\"Não consegui reabrir o pedido.\"); return; }\n        iniciarPedidoRep(res.j.cliente);     // abre o catálogo montando pedido pra esse cliente\n        REP_PEDIDO_ID=id;                    // continua editando ESTE rascunho\n        REP_PEDIDO_FORMA=res.j.cod_prazo||\"\"; REP_PEDIDO_OBS=res.j.observacao||\"\";\n        CART=(res.j.itens||[]).map(reconstruirItemCart);\n        salvarCart(); atualizarCartN(); abrirCarrinho();\n      })\n      .catch(function(){ alert(\"Sem conexão. Tente de novo.\"); });\n  };\n  window.__repPedExcluir=function(id){\n    if(!confirm(\"Excluir este pedido em espera? Não dá pra desfazer.\")) return;\n    fetch(\"/api/loja/rep-pedido-acao\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({rep:(REP&&REP.id)||\"\",pedido_id:id,acao:\"excluir\"})})\n      .then(function(r){return r.json();}).then(function(j){ if(j&&j.ok){ carregarRepPedidos(); } else { alert((j&&j.msg)||\"Não consegui excluir.\"); } })\n      .catch(function(){ alert(\"Sem conexão. Tente de novo.\"); });\n  };\n  window.__repPedEnviar=function(id,temForma){\n    var cod_prazo=\"\", forma_desc=\"\";\n    if(!temForma){\n      if(!REP_PRAZOS.length){ alert(\"Carregando formas de pagamento… tente de novo em instantes.\"); return; }\n      var lista=REP_PRAZOS.map(function(p,i){ return (i+1)+\") \"+(p.descricao||p.codigo); }).join(\"\\n\");\n      var escolha=prompt(\"Escolha a forma de pagamento (digite o número):\\n\"+lista);\n      if(escolha===null) return;\n      var idx=parseInt(escolha,10)-1;\n      if(isNaN(idx)||idx<0||idx>=REP_PRAZOS.length){ alert(\"Opção inválida.\"); return; }\n      cod_prazo=REP_PRAZOS[idx].codigo; forma_desc=REP_PRAZOS[idx].descricao||REP_PRAZOS[idx].codigo;\n    }\n    if(!confirm(\"Enviar este pedido para a Big Tricot?\\nDepois de enviado ele trava.\")) return;\n    fetch(\"/api/loja/rep-pedido-acao\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify({rep:(REP&&REP.id)||\"\",pedido_id:id,acao:\"enviar\",cod_prazo:cod_prazo,forma_desc:forma_desc})})\n      .then(function(r){return r.json();}).then(function(j){ if(j&&j.ok){ alert(j.msg||\"Pedido enviado!\"); carregarRepPedidos(); } else { alert((j&&j.msg)||\"Não consegui enviar.\"); } })\n      .catch(function(){ alert(\"Sem conexão. Tente de novo.\"); });\n  };\n  window.__repCliente=function(id){\n    var cli=null; for(var i=0;i<REP_CLIENTES.length;i++){ if(String(REP_CLIENTES[i].id)===String(id)){ cli=REP_CLIENTES[i]; break; } }\n    if(!cli) return;\n    if(cli.bloqueado){ alert(\"Este cliente está bloqueado. Fale com a Big Tricot.\"); return; }\n    if(!cli.liberado){ alert(\"Este cliente ainda está em análise. Assim que a Big Tricot liberar, você poderá montar o pedido dele. 💛\"); return; }\n    iniciarPedidoRep(cli);\n  };\n  function iniciarPedidoRep(cli){\n    REP_CLIENTE=cli;\n    REP_PEDIDO_ID=\"\"; REP_PEDIDO_FORMA=\"\"; REP_PEDIDO_OBS=\"\";  // novo pedido pra esse cliente\n    regiao=(cli.regiao===\"norte\")?\"norte\":\"sul\";\n    LIBERADO=!!cli.liberado;\n    try{ localStorage.setItem(\"bt_cnpj\", String(cli.cnpj||\"\").replace(/\\D+/g,\"\")); }catch(e){}  // pro checkout e \"meus pedidos\"\n    if(!REP_PRAZOS.length){ fetch(\"/api/loja/prazos\").then(function(r){return r.json();}).then(function(j){ if(Array.isArray(j)) REP_PRAZOS=j; }).catch(function(){}); }\n    document.getElementById(\"repArea\").style.display=\"none\";\n    document.body.style.overflow=\"\";\n    // Modo rep: cara de app de vendas — some o banner/hero e mostra o cliente no cabeçalho.\n    try{ document.body.classList.add(\"rep-mode\"); }catch(e){}\n    var ban=document.getElementById(\"banner\"); if(ban) ban.style.display=\"none\";\n    var sa=document.getElementById(\"saudacao\");\n    if(sa){ sa.style.display=\"flex\"; sa.innerHTML='<b style=\"color:#fff\">'+esc(cli.nome||cli.fantasia||\"Cliente\")+'</b>'; }\n    atualizarAvisoLib();\n    var bar=document.getElementById(\"repPedBar\"); bar.style.display=\"none\"; // substituído pelo Voltar no cabeçalho\n    render(); if(document.getElementById(\"modal\").classList.contains(\"show\")) renderDetalhe();\n    try{ window.scrollTo({top:0}); }catch(e){}\n  }\n  // Catálogo em modo \"só ver\": rep vê produtos e preços, mas não monta pedido (sem cliente).\n  function iniciarRepVerProdutos(){\n    REP_CLIENTE=null; REP_SOVER=true; REP_PEDIDO_ID=\"\";\n    regiao=\"sul\"; LIBERADO=true;  // rep vê preços de referência\n    document.getElementById(\"repArea\").style.display=\"none\";\n    document.body.style.overflow=\"\";\n    try{ document.body.classList.add(\"rep-mode\"); document.body.classList.add(\"rep-sover\"); }catch(e){}\n    var ban=document.getElementById(\"banner\"); if(ban) ban.style.display=\"none\";\n    var sa=document.getElementById(\"saudacao\");\n    if(sa){ sa.style.display=\"flex\"; sa.innerHTML='<b style=\"color:#fff\">Catálogo</b> · só visualização'; }\n    atualizarAvisoLib();\n    document.getElementById(\"repPedBar\").style.display=\"none\";\n    render(); if(document.getElementById(\"modal\").classList.contains(\"show\")) renderDetalhe();\n    try{ window.scrollTo({top:0}); }catch(e){}\n  }\n  window.__repVoltarArea=function(){\n    REP_CLIENTE=null; REP_SOVER=false;\n    document.getElementById(\"repPedBar\").style.display=\"none\";\n    try{ document.body.classList.remove(\"rep-mode\"); document.body.classList.remove(\"rep-sover\"); }catch(e){}\n    var ban=document.getElementById(\"banner\"); if(ban) ban.style.display=\"\";\n    mostrarSaudacao(\"\");\n    document.getElementById(\"repArea\").style.display=\"block\";\n    document.body.style.overflow=\"\";\n    __repHome();\n  };\n  // Puxar dados da Receita pelo CNPJ (preenche os campos). O rep confere e-mail/WhatsApp.\n  function repPuxarReceita(){\n    var cnpj=(document.getElementById(\"rnCnpj\").value||\"\").replace(/\\D/g,\"\");\n    var msg=document.getElementById(\"rncMsg\"), btn=document.getElementById(\"rnReceita\");\n    var lbl=document.getElementById(\"rnRecLbl\");\n    if(cnpj.length!==14){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Digite o CNPJ completo (14 dígitos) pra buscar na Receita.\"; return; }\n    msg.textContent=\"\"; btn.disabled=true; lbl.textContent=\"Buscando…\";\n    fetch(\"/api/loja/consulta-cnpj?cnpj=\"+encodeURIComponent(cnpj))\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        btn.disabled=false; lbl.textContent=\"Buscar\";\n        if(res.ok && res.j.ok){\n          var d=res.j.dados||{};\n          var set=function(id,v){ var e=document.getElementById(id); if(e && v) e.value=v; };\n          set(\"rnNome\",d.razao_social); set(\"rnFant\",d.fantasia||d.razao_social); set(\"rnEnd\",d.endereco); set(\"rnNum\",d.numero); set(\"rnBai\",d.bairro); set(\"rnCep\",d.cep); set(\"rnCid\",d.cidade); set(\"rnUf\",d.uf); set(\"rnTel\",d.telefone); set(\"rnEmail\",d.email);\n          msg.style.color=\"#166534\"; msg.innerHTML=\"✓ Dados da Receita preenchidos. <b>Confira o e-mail e o WhatsApp</b> — às vezes estão desatualizados.\";\n        } else { msg.style.color=\"#b91c1c\"; msg.textContent=res.j.msg||\"Não consegui puxar da Receita. Preencha à mão.\"; }\n      })\n      .catch(function(){ btn.disabled=false; lbl.textContent=\"Buscar\"; msg.style.color=\"#b91c1c\"; msg.textContent=\"Sem conexão com a Receita. Preencha à mão.\"; });\n  }\n  // Cadastro de cliente novo pelo REP (vai pra fila de aprovação, atrelado ao rep).\n  function repEnviarNovoCli(){\n    var g=function(id){ return (document.getElementById(id).value||\"\").trim(); };\n    var msg=document.getElementById(\"rncMsg\"), btn=document.getElementById(\"rnBtn\");\n    var isento=document.getElementById(\"rnIsento\").checked;\n    var ie = isento ? \"ISENTO\" : g(\"rnIe\");\n    var body={ rep_id:(REP&&REP.id)||\"\", nome:g(\"rnNome\"), fantasia:g(\"rnFant\"), cnpj:g(\"rnCnpj\"), inscricao:ie, endereco:g(\"rnEnd\"), numero:g(\"rnNum\"), bairro:g(\"rnBai\"), cep:g(\"rnCep\"), uf:g(\"rnUf\"), cidade:g(\"rnCid\"), email:g(\"rnEmail\"), whatsapp:g(\"rnTel\"), telefone:g(\"rnTel\") };\n    function falta(m){ msg.style.color=\"#b91c1c\"; msg.textContent=m; }\n    if(body.cnpj.replace(/\\D/g,\"\").length<11) return falta(\"Informe o CNPJ.\");\n    if(!body.nome) return falta(\"Informe a razão social.\");\n    if(!body.fantasia) return falta(\"Informe o nome fantasia.\");\n    if(!ie) return falta(\"Informe a inscrição estadual (ou marque Isento).\");\n    if(!body.endereco) return falta(\"Informe o endereço.\");\n    if(!body.cidade || !body.uf) return falta(\"Informe cidade e UF.\");\n    if(!body.whatsapp) return falta(\"Informe o WhatsApp.\");\n    if(!body.email || body.email.indexOf(\"@\")<0) return falta(\"Informe um e-mail válido.\");\n    msg.textContent=\"\"; btn.disabled=true; btn.textContent=\"Enviando…\";\n    fetch(\"/api/loja/rep-cadastrar-cliente\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body)})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        btn.disabled=false; btn.textContent=\"Enviar cadastro\";\n        if(res.ok && res.j.ok){\n          if(res.j.clientes) REP_CLIENTES=res.j.clientes;\n          document.getElementById(\"repTileCount\").textContent=REP_CLIENTES.length+\" cliente\"+(REP_CLIENTES.length===1?\"\":\"s\");\n          var nomeCad=g(\"rnFant\")||g(\"rnNome\")||\"Cliente\";\n          var cnpjCad=(g(\"rnCnpj\")||res.j.cnpj||\"\").replace(/\\D/g,\"\");\n          [\"rnNome\",\"rnFant\",\"rnCnpj\",\"rnIe\",\"rnEnd\",\"rnNum\",\"rnBai\",\"rnCep\",\"rnUf\",\"rnCid\",\"rnEmail\",\"rnTel\"].forEach(function(id){ var e=document.getElementById(id); if(e) e.value=\"\"; });\n          var iso=document.getElementById(\"rnIsento\"); if(iso) iso.checked=false;\n          // Cliente já vem liberado (rep normalmente está na loja). Mostra tela de sucesso\n          // com botão pra seguir direto pro pedido.\n          document.getElementById(\"repOkNome\").textContent=nomeCad;\n          repMostrarSub(\"repNovoOk\");\n          REP_NOVO_CNPJ=cnpjCad;\n        } else { msg.style.color=\"#b91c1c\"; msg.textContent=res.j.msg||\"Não consegui enviar. Confira os dados.\"; }\n      })\n      .catch(function(){ btn.disabled=false; btn.textContent=\"Enviar cadastro\"; msg.style.color=\"#b91c1c\"; msg.textContent=\"Sem conexão. Tente de novo.\"; });\n  }\n  function repSair(){ try{ localStorage.removeItem(\"bt_rep\"); localStorage.removeItem(\"bt_cnpj\"); }catch(e){} REP=null; REP_CLIENTE=null; try{ location.href=location.pathname; return; }catch(e){} document.getElementById(\"repArea\").style.display=\"none\"; mostrarEnt(); abrirEntrada(); }\n  document.getElementById(\"repBtn\").addEventListener(\"click\",repEntrar);\n  document.getElementById(\"repSenha\").addEventListener(\"keydown\",function(e){ if(e.key===\"Enter\") repEntrar(); });\n  // \"Entrar como representante\" leva pro PORTAL do rep (?rep=1), separado do catálogo do cliente.\n  document.getElementById(\"irRep\").addEventListener(\"click\",function(){ try{ location.href=location.pathname+\"?rep=1\"; }catch(e){ mostrarRepView(); } });\n  // \"Voltar\" na tela de login do rep volta pro catálogo do cliente (tira o ?rep=1).\n  document.getElementById(\"repVoltar\").addEventListener(\"click\",function(){ try{ if(new URLSearchParams(location.search).get(\"rep\")===\"1\"){ location.href=location.pathname; return; } }catch(e){} mostrarEnt(); });\n  document.getElementById(\"repSair\").addEventListener(\"click\",repSair);\n  document.getElementById(\"rnBtn\").addEventListener(\"click\",repEnviarNovoCli);\n  document.getElementById(\"rnReceita\").addEventListener(\"click\",repPuxarReceita);\n  document.getElementById(\"repBusca\").addEventListener(\"input\",desenharCarteira);\n  // Tela de sucesso do cadastro: seguir pro pedido ou voltar ao menu.\n  document.getElementById(\"repOkPedido\").addEventListener(\"click\",function(){\n    var cli=null, dig=String(REP_NOVO_CNPJ||\"\").replace(/\\D/g,\"\");\n    for(var i=0;i<REP_CLIENTES.length;i++){ if(String(REP_CLIENTES[i].cnpj||\"\").replace(/\\D/g,\"\")===dig){ cli=REP_CLIENTES[i]; break; } }\n    if(cli){ iniciarPedidoRep(cli); } else { __repSecao(\"carteira\"); }\n  });\n  document.getElementById(\"repOkFechar\").addEventListener(\"click\",function(){ __repHome(); });\n  (function(){ var iso=document.getElementById(\"rnIsento\"); if(iso) iso.addEventListener(\"change\",function(){ var ie=document.getElementById(\"rnIe\"); if(ie){ ie.disabled=iso.checked; ie.value=iso.checked?\"\":ie.value; ie.style.opacity=iso.checked?.5:1; } }); })();\n\n  // Cadastro de loja nova (abre dentro do mesmo modal de entrada)\n  function mostrarCad(prefill){ document.getElementById(\"entView\").style.display=\"none\"; document.getElementById(\"cadView\").style.display=\"block\"; var cc=document.getElementById(\"cCnpj\"); if(cc && prefill && !cc.value) cc.value=prefill; document.getElementById(\"cadMsg\").textContent=\"\"; }\n  function mostrarEnt(){ [\"cadView\",\"senhaView\",\"repView\"].forEach(function(id){ var e=document.getElementById(id); if(e) e.style.display=\"none\"; }); document.getElementById(\"entView\").style.display=\"block\"; }\n  document.getElementById(\"irCad\").addEventListener(\"click\",function(){ mostrarCad((document.getElementById(\"entCnpj\").value||\"\").trim()); });\n  document.getElementById(\"voltarEnt\").addEventListener(\"click\",mostrarEnt);\n  function enviarCadastro(){\n    var g=function(id){ return (document.getElementById(id).value||\"\").trim(); };\n    var msg=document.getElementById(\"cadMsg\"), btn=document.getElementById(\"cadBtn\");\n    var senha=g(\"cSenha\"), senha2=g(\"cSenha2\");\n    var body={ nome:g(\"cNome\"), fantasia:g(\"cFant\"), cnpj:g(\"cCnpj\"), inscricao:g(\"cIe\"), endereco:g(\"cEnd\"), numero:g(\"cNum\"), bairro:g(\"cBai\"), cep:g(\"cCep\"), uf:g(\"cUf\"), cidade:g(\"cCid\"), email:g(\"cEmail\"), whatsapp:g(\"cTel\"), telefone:g(\"cTel\"), senha:senha };\n    if(!body.nome || !body.cidade || !body.uf || body.cnpj.replace(/\\D/g,\"\").length<11){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Preencha pelo menos Razão social, CNPJ, Cidade e UF.\"; return; }\n    if(senha.length<4){ msg.style.color=\"#b91c1c\"; msg.textContent=\"Crie uma senha com pelo menos 4 caracteres.\"; return; }\n    if(senha!==senha2){ msg.style.color=\"#b91c1c\"; msg.textContent=\"As senhas não são iguais.\"; return; }\n    msg.textContent=\"\"; btn.disabled=true; btn.textContent=\"Enviando…\";\n    fetch(\"/api/loja/cadastro\",{method:\"POST\",headers:{\"Content-Type\":\"application/json\"},body:JSON.stringify(body)})\n      .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n      .then(function(res){\n        btn.disabled=false; btn.textContent=\"Enviar cadastro\";\n        if(res.j.ok){\n          // Cadastro novo criado: já loga (em análise, sem preços). Senão, mostra a mensagem.\n          if(res.j.criado){ try{ localStorage.setItem(\"bt_cnpj\", body.cnpj); }catch(e){} aplicarSessao(body.nome, \"sul\", false); }\n          else { msg.style.color=\"#166534\"; msg.textContent=res.j.msg||\"Cadastro recebido!\"; btn.style.display=\"none\"; var grid=document.querySelector(\"#cadView [style*='grid']\"); if(grid) grid.style.display=\"none\"; }\n        }\n        else { msg.style.color=\"#b91c1c\"; msg.textContent=res.j.msg||\"Não consegui enviar. Confira os dados.\"; if(res.j.erro===\"ja_cadastrado\") setTimeout(mostrarEnt,2200); }\n      })\n      .catch(function(){ btn.disabled=false; btn.textContent=\"Enviar cadastro\"; msg.style.color=\"#b91c1c\"; msg.textContent=\"Sem conexão. Tente de novo.\"; });\n  }\n  document.getElementById(\"cadBtn\").addEventListener(\"click\",enviarCadastro);\n\n  // Banner pode abrir um produto do catálogo ao clicar (chamado pelo onclick do banner).\n  window.__abrirProd=function(id){ try{ abrir(id); window.scrollTo({top:0,behavior:\"smooth\"}); }catch(e){} };\n  atualizarCartN();\n  renderBanner();\n  render();\n  ligarWhatsApp();\n\n  // Inicia sessão: trata link de acesso (?acesso=token), senão usa o que está salvo e revalida.\n  (function iniciarSessao(){\n    var qs; try{ qs=new URLSearchParams(location.search); }catch(e){ qs=null; }\n    // 0) Link de acesso do REPRESENTANTE (?rep_acesso=token): ele cria a senha dele.\n    var rtok = qs ? (qs.get(\"rep_acesso\")||\"\") : \"\";\n    if(rtok){\n      fetch(\"/api/loja/rep-acesso?token=\"+encodeURIComponent(rtok))\n        .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n        .then(function(res){\n          if(res.ok && res.j.ok){\n            if(res.j.tem_senha){ mostrarRepView(); }\n            else { TOKEN_REP=rtok; mostrarCriarSenha(res.j.nome, \"\"); }\n          } else { mostrarEnt(); abrirEntrada(); }\n        })\n        .catch(function(){ mostrarEnt(); abrirEntrada(); });\n      return;\n    }\n    // 0b) PORTAL DO REPRESENTANTE (?rep=1): área do rep é SEPARADA do catálogo do cliente.\n    //     Só abre a área do rep aqui; no /loja puro nunca cai na tela do representante.\n    var ehPortalRep = qs && qs.get(\"rep\")===\"1\";\n    if(ehPortalRep){\n      var rep=repSalvo();\n      if(rep && rep.id){\n        fetch(\"/api/loja/rep-carteira?rep=\"+encodeURIComponent(rep.id))\n          .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n          .then(function(res){ if(res.ok && res.j.ok){ aplicarRep(res.j.rep, res.j.clientes); } else { try{ localStorage.removeItem(\"bt_rep\"); }catch(e){} mostrarRepView(); } })\n          .catch(function(){ aplicarRep(rep, []); });\n      } else {\n        mostrarRepView();  // portal do rep sem login → tela de login do representante\n      }\n      return;\n    }\n    // ---- daqui pra baixo é o CATÁLOGO DO CLIENTE (nunca abre a área do representante) ----\n    var c=cliSalvo(); if(c && c.regiao){ regiao=(c.regiao===\"norte\")?\"norte\":\"sul\"; LIBERADO=!!c.liberado; mostrarSaudacao(c.nome); atualizarAvisoLib(); }\n    // 1) Link de acesso enviado pelo gestor: o cliente cria a senha dele.\n    var tok=\"\"; try{ tok=qs?(qs.get(\"acesso\")||\"\"):\"\"; }catch(e){}\n    if(tok){\n      TOKEN_ACESSO=tok;\n      fetch(\"/api/loja/acesso?token=\"+encodeURIComponent(tok))\n        .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n        .then(function(res){\n          if(res.ok && res.j.ok){\n            if(res.j.tem_senha){ TOKEN_ACESSO=\"\"; mostrarEnt(); abrirEntrada(); }   // já tem senha → login normal\n            else { mostrarCriarSenha(res.j.nome, res.j.cnpj_mascara); }               // 1º acesso → cria senha\n          } else { TOKEN_ACESSO=\"\"; mostrarEnt(); abrirEntrada(); }\n        })\n        .catch(function(){ TOKEN_ACESSO=\"\"; abrirEntrada(); });\n      return;\n    }\n    // 2) Sessão já salva: confirma rapidinho (sem senha) o estado atual.\n    var dig=(cnpjSalvo()||\"\").replace(/\\D+/g,\"\");\n    if(dig.length>=11){\n      fetch(\"/api/loja/sessao?cnpj=\"+encodeURIComponent(cnpjSalvo()))\n        .then(function(r){ return r.json().then(function(j){ return {ok:r.ok,j:j||{}}; }); })\n        .then(function(res){ if(res.ok && res.j.ok){ aplicarSessao(res.j.nome,res.j.regiao,res.j.liberado); } else { sairLoja(); } })\n        .catch(function(){ /* offline: segue com o que estava salvo */ });\n    } else { abrirEntrada(); }\n  })();\n})();\n</script>\n</body>\n</html>\n";
